/**
 * 负责原生命死亡提交与唯一的已结算生命账本。输入是有序玩家名单、原死亡原因，以及
 * 延迟读取结算器 World、事件数组和运行状态的上下文；输出是原 Alive 修改、事实事件、
 * 待过期枪列表、继承更新及成功提交凭证。isSettledLife 仅查询，markPlayersDead 是专用死亡写命令。
 * 本所有者不收集死亡波、遗言、枪击选择或警徽决定，不切换阶段，也不执行枪的最终过期。
 * 写入与记录失败均保留原先已提交的前缀，不回滚或提前发布已结算账本条目。
 */
import {
  DeathCommitReceipt,
  committedDeathEntry,
  planDeathWave,
  type DeathCommitEntry,
  type DeathWavePlan,
} from "./death-wave";
import { getSessionRecorder } from "../../recording/recording_context";
import { isRoleId } from "@ai-werewolf-arena/game-contract";
import { aliveLifeVersion, type AliveComponent } from "../../core/domain/components/alive";
import { COMPONENT } from "../../core/domain/components/names";
import {
  DeathCause,
  Role,
  type EntityId,
  type GameEvent,
  type RuntimeSnapshot,
  type DeathSources,
} from "../../core/domain/model";
import type { World } from "../../core/domain/world";
import {
  isAnimalDreamBoard,
  commitAnimalPufferKnifeDeath,
} from "../mechanisms/roles/animal_dream/ports";
import {
  isNobleBodyBoard,
  closeServantForDeath,
} from "../mechanisms/roles/noble_secret_body/ports";
import { appendNobleContractClosure } from "../mechanisms/roles/noble_secret_body/ports";
import { recordWildChildDeathCommit } from "../mechanisms/roles/wild_child/ports";
import { firstDeathGuns } from "../mechanisms/roles/death_abilities";
import { expireLuckyAbilitiesOnDeath } from "../mechanisms/roles/ability_changes";
import { refreshHiddenWolfInheritance } from "../mechanisms/roles/hidden_wolf/ports";
import { refreshGargoyleInheritance } from "../mechanisms/roles/gargoyle/ports";
import { refreshMechanicalInheritance } from "../mechanisms/roles/mechanical_wolf/ports";
import { refreshAwakenedInheritance } from "../mechanisms/roles/awakened_hidden_wolf/ports";

/** 访问器由结算器传入；每次读取原 World／事件／状态，不把 readonly 声明当作运行时写权限隔离。 */
interface DeathCommitContext {
  readonly world: World;
  readonly events: GameEvent[];
  readonly state: RuntimeSnapshot;
}

export class DeathCommitter {
  // 每个序号仅记原 Alive 对象与其生命版本；复活或替换组件必须重新结算。
  private readonly settledLives = new Map<
    EntityId,
    { component: AliveComponent; version: number | undefined }
  >();

  constructor(private readonly context: DeathCommitContext) {}

  isSettledLife(id: EntityId): boolean {
    const alive = this.context.world.getComponent(id, COMPONENT.Alive),
      settled = this.settledLives.get(id);
    return (
      alive !== undefined &&
      settled?.component === alive &&
      settled.version === aliveLifeVersion(alive)
    );
  }

  /**
   * 按原名单顺序提交；账本控制首次死亡分支（事实、被动／关系提交与揭示），不替调用方过滤重复 ID。
   * 重入仍写 Alive、收集枪并检查能力到期；gunsToExpire 由外层累积，这里仅追加。
   * 追加枪波关闭继承刷新，由外层在原位置执行；异常保留已提交的玩家和事实前缀。
   */
  markPlayersDead(
    playerIds: EntityId[],
    refreshInheritance = true,
    gunsToExpire: ReturnType<typeof firstDeathGuns> = [],
    reveal = false,
    sources: DeathSources = {},
    animalScope?: object | (() => boolean),
    wave?: DeathWavePlan,
  ): DeathCommitReceipt {
    if (wave && (wave.ids !== playerIds || wave.sources !== sources))
      throw new Error("death_wave_commit_input_mismatch");
    const committedWave = wave ?? planDeathWave(playerIds, sources, "legacy");
    const entries: DeathCommitEntry[] = [];
    for (const id of playerIds) {
      const alive = this.context.world.getComponent(id, COMPONENT.Alive);
      if (!alive) {
        continue;
      }
      // 先记野孩子的活跃生命死亡，再改 Alive；不能把首次判断移到修改之后。
      const firstSettlement = !this.isSettledLife(id);
      if (firstSettlement) recordWildChildDeathCommit(this.context.world, id);
      alive.alive = false;
      if (firstSettlement && isAnimalDreamBoard(this.context.world)) {
        if (
          (sources[id] ?? []).includes(DeathCause.WolfKill) &&
          this.context.world.getComponent(id, COMPONENT.Role)?.role === Role.Pufferfish
        ) {
          commitAnimalPufferKnifeDeath(
            this.context.world,
            this.context.state.day,
            sources[id] ?? [],
            animalScope ?? (() => !this.context.state.gameOver),
          );
        }
        if ((sources[id] ?? []).includes(DeathCause.Exile))
          this.context.events.push({
            timestamp: Date.now(),
            type: "voted_out",
            payload: { target: id },
          });
        else if (
          (sources[id] ?? []).some(
            (c) => c === DeathCause.PufferRetaliation || c === DeathCause.WhiteCatExpiry,
          )
        )
          this.context.events.push({
            timestamp: Date.now(),
            type: "additional_deaths",
            payload: { deaths: [id] },
          });
      }
      if (firstSettlement && isNobleBodyBoard(this.context.world)) {
        const closed = closeServantForDeath(this.context.world, this.context.state.day, id);
        const payload = {
          policy: "awa_noble_secret_body_v1" as const,
          actorId: id,
          day: this.context.state.day,
          causes: [...(sources[id] ?? [])],
        };
        this.context.events.push({
          timestamp: Date.now(),
          type: "noble_body_death_committed",
          payload,
          audience: Object.freeze([]),
        });
        getSessionRecorder()?.recordRequiredLogicOp({
          scope: "resolution",
          op: "noble_body_death_committed",
          phase: this.context.state.phase,
          status: "ok",
          output: {
            policy: payload.policy,
            playerId: id,
            day: payload.day,
            causes: payload.causes,
          },
        });
        if (closed)
          appendNobleContractClosure(
            this.context.world,
            this.context.state.day,
            closed,
            this.context.events,
            this.context.state.phase,
          );
      }
      const role = this.context.world.getComponent(id, COMPONENT.Role)?.role;
      if (reveal && firstSettlement && isRoleId(role))
        this.context.events.push({
          timestamp: Date.now(),
          type: "player_role_revealed",
          payload: { playerId: id, role },
        });
      gunsToExpire.push(...firstDeathGuns(this.context.world, id));
      expireLuckyAbilitiesOnDeath(this.context.world, id, this.context.events);
      // 事实、记录、枪列表和能力过期均成功之后才发布账本；任何早期异常不伪造完成。
      // 此前已改 Alive 或写出部分事实也不回滚；账本缺项不表示该目标尚未产生任何副作用。
      let settled: { component: AliveComponent; version: number | undefined };
      this.settledLives.set(id, (settled = { component: alive, version: aliveLifeVersion(alive) }));
      // 凭证复用已写账本的原条目；此后失败仍不返回成功凭证，也不撤销此前死亡。
      Object.freeze(settled);
      entries.push(committedDeathEntry(committedWave, id, firstSettlement, settled));
    }
    // 整波生命提交之后按原顺序刷新继承；此处失败不能撤销已写入的生命与账本。
    if (refreshInheritance) {
      refreshHiddenWolfInheritance(this.context.world, this.context.events, this.context.state.day);
      refreshGargoyleInheritance(this.context.world, this.context.events, this.context.state.day);
      refreshMechanicalInheritance(this.context.world, this.context.state.day, this.context.events);
      refreshAwakenedInheritance(this.context.world, this.context.state.day, this.context.events);
    }
    // 命令正常返回才交出本次条目；它不证明后续遗言／死亡钩子／枪付款或最终判胜已完成。
    return new DeathCommitReceipt(committedWave, Object.freeze(entries));
  }
}

/**
 * 负责普通夜能力原生安装、起效日、启停、次数、首次死亡到期及借用实例退役。
 * 输入为原角色／实例、状态与业务日期；输出保留同一库存引用和能力变化事实。授予、复制、转移完整流程归 night-ability-grants。
 * 本模块只写原生安装及公共 metadata；具体 payload 库存、临时抑制、原体／生命和提交许可仍归原负责人。
 * 共用角色查询／发布唯一消费 night-ability-change-runtime，保留原 clone、getter、字段和部分失败前缀，不退款。
 */
import type {
  NightAbilityKind,
  NightAbilityStates,
  NightAbilityReadState,
  RoleInspectionState,
} from "@ai-werewolf-arena/game-contract";

import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { Role, type EntityId, type GameEvent } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import { allNightAbilities, abilityStatus, projectPairState, copyAbilityData, type NightAbilityReadView } from "./abilities";
import { roleOf, emit } from "./night-ability-change-runtime";

import { commitPreparedNativeAbility } from "./prepared-native-install";
import { DREAMER_STATE_SLOT } from "./dreamer/ports";
import { SHELTER_STATE_SLOT } from "./radiant_eclipse/shelter-state-slot";
import { SEER_STATE_SLOT } from "./seer/ports";
import { GUARD_STATE_SLOT } from "./guard/ports";
import { WITCH_STATE_SLOT } from "./witch/ports";
import { ROLE_INSPECTION_STATE_SLOT } from "./role_inspection/ports";

export function setNightAbilityEnabled(
  world: World,
  actorId: EntityId,
  id: string,
  enabled: boolean,
  events: GameEvent[],
): void {
  const ability = allNightAbilities(roleOf(world, actorId)).find((ability) => ability.id === id);
  if (!ability) throw new Error("ability_instance_missing");
  if (enabled && ability.deathExpired) throw new Error("ability_lucky_expired_on_death");
  if (ability.disabled === !enabled) return;
  (ability as { disabled: boolean }).disabled = !enabled;
  emit(events, actorId, ability, enabled ? "enabled" : "disabled");
}

/**
 * 退役角色已核对原体／捕获槽的借用实例，只重定义原 disabled 数据属性。
 * 目标 supplier 在 Object.defineProperty 方法查找之后执行，保原 late 字段读取位置。
 * 不按可变 id 重查、不读或执行替换的 disabled getter/setter、不删槽／退休 ID，不发布启停事实。
 * 借用租约、原主抑制和已付 payload 仍归具体 Frame；本写入不提供新行动权限或退款。
 */
export function retireBorrowedNightAbility(readBorrowed: () => NightAbilityReadView): void {
  Object.defineProperty(readBorrowed(), "disabled", {
    value: true,
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

/** 实际死亡到期跟随同一实例经过转移／复活；已经付款的夜效果仍按原政策保留。 */
export function expireLuckyAbilitiesOnDeath(
  world: World,
  actorId: EntityId,
  events: GameEvent[],
): void {
  for (const ability of allNightAbilities(world.getComponent(actorId, COMPONENT.Role))) {
    if (
      (ability.activation !== "lucky" && ability.activation !== "black_market") ||
      ability.deathExpired
    )
      continue;
    (ability as { deathExpired?: boolean }).deathExpired = true;
    (ability as { disabled: boolean }).disabled = true;
    emit(events, actorId, ability, "disabled");
  }
}

/** 原生安装先完成原 copy／policy，再写实际 abilities 槽；不提前读取退休 ID 或更换私有容器。 */
export function installNativeAbility<K extends NightAbilityKind>(
  role: RoleComponent,
  kind: K,
  state: NightAbilityStates[K],
): NightAbilityReadState<K> {
  if (kind === "pair_check" && role.role !== Role.AwakenedSeer)
    throw Error("ability_pair_native_role_invalid");
  const ownedState = (
    kind === "pair_check"
      ? copyAbilityData(projectPairState(state))
      : kind === "role_check"
        ? ROLE_INSPECTION_STATE_SLOT.create(state as RoleInspectionState)
        : kind === "seer_check"
          ? SEER_STATE_SLOT.create(state as NightAbilityStates["seer_check"])
          : kind === "guard"
            ? GUARD_STATE_SLOT.create(state as NightAbilityStates["guard"])
            : kind === "potion"
              ? WITCH_STATE_SLOT.create(state as NightAbilityStates["potion"])
              : kind === "dream"
                ? DREAMER_STATE_SLOT.create(state as NightAbilityStates["dream"])
                : kind === "shelter"
                  ? SHELTER_STATE_SLOT.prepare(state as NightAbilityStates["shelter"])
                  : copyAbilityData(state)
  ) as NightAbilityStates[K];
  return commitPreparedNativeAbility(role, kind, ownedState);
}

/** 初始化／学习流程仍在原调用点决定起效日；这里只写原 startsOnDay，不推进业务时钟。 */
export function setNightAbilityStartDay(ability: NightAbilityReadView, day: number): void {
  (ability as { startsOnDay: number }).startsOnDay = day;
}

/** 原 status 重检后先记 lastUsedDay，再可选增加 uses；payload 库存与已付效果继续归具体机制。 */
export function recordNightAbilityUse(
  ability: NightAbilityReadView,
  day: number,
  consumed: boolean,
): void {
  if (abilityStatus(ability, day) !== "active") throw new Error("ability_not_active");
  (ability as { lastUsedDay: number | null }).lastUsedDay = day;
  if (consumed) (ability as { uses: number }).uses++;
}

/**
 * 负责觉醒隐狼开夜、学习、技能、额外刀和激活阶段。
 * 输入为原 native/copy scope 与已验证工具；输出为原已付事实及有来源的盾、刀和原毒 intent。
 * 复用原捕获 life/day/目标，保留付款位置以及允许首次死亡的 paid callback。
 * 不以新来源数据替代资格、库存或重试规则，不恢复撤销的原 owner，不改变阶段优先级或归档。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase, StatusMark, type EntityId, type ToolName } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  awakenedNightIntent,
  originalPoisonIntent,
} from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { allNightAbilities, findNightAbility, retiredNightAbilityIds } from "../abilities";
import { setNightAbilityStartDay, installNativeAbility } from "../ability_changes";
import { canAwakenedKnife } from "./inheritance";
import {
  beginAwakenedNight,
  bindAwakenedSkill,
  captureAwakenedOwner,
  currentAwakenedNight,
  recordAwakenedNightCommit,
} from "./night_scope";
import {
  activateAwakenedLearning,
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  chooseAwakenedAttack,
  chooseAwakenedGuard,
  closeAwakenedMimic,
  learnAwakenedRole,
  skipAwakenedSkill,
  useAwakenedPoison,
} from "./state";

function owners(ctx: NightStageContext, day: number, opening = false) {
  return ctx.world.getAliveEntityIds().flatMap((id) => {
    const owner = captureAwakenedOwner(
      ctx.world,
      id,
      () => ctx.isCurrent() && ctx.currentDay() === day,
    );
    return owner && (opening || currentAwakenedNight(ctx.world, owner.role) === day) ? [owner] : [];
  });
}
const targets = (ctx: NightStageContext, actorId: EntityId, excludeSelf: boolean) =>
  new Map(
    ctx.world
      .getAliveEntityIds()
      .filter((id) => !excludeSelf || id !== actorId)
      .map((id) => [id, captureNightLife(ctx.world, id)!] as const),
  );
const effects = (ctx: NightStageContext) =>
  (ctx.state.awakenedEffects ??= { shields: [], attacks: [] });
const retry = (attempt: number) => (attempt ? { retry_attempt: attempt, retry_max: 2 } : {});

const openingStage: NightStageHandler = {
  id: "awakened_opening",
  priority: 250,
  async execute(ctx) {
    const day = ctx.currentDay();
    beginAwakenedNight(ctx.world, day, owners(ctx, day, true));
  },
};
const mimicStage: NightStageHandler = {
  id: "awakened_mimic",
  priority: 580,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      if (!canAwakenedMimic(owner.state, day)) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!owner.isCurrent() || !canAwakenedMimic(owner.state, day)) break;
        const candidates = targets(ctx, owner.actorId, true);
        const roles = new Map(
          [...candidates.keys()].map((id) => {
            const component = ctx.world.getComponent(id, COMPONENT.Role)!;
            return [id, { component, role: component.role, camp: component.camp }] as const;
          }),
        );
        const action = candidates.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(owner.actorId, ["awakened_mimic"], {
                stage: "awakened_mimic",
                requiresAction: false,
                action_failure_policy: "error",
                allow_fallback: false,
                ...retry(attempt),
              }),
            )
          : null;
        if (!owner.isCurrent() || !canAwakenedMimic(owner.state, day)) break;
        if (action === null) {
          closeAwakenedMimic(owner.state, day);
          recordAwakenedNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_mimic_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "awakened_mimic") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (
          !owner.isCurrent() ||
          !canAwakenedMimic(owner.state, day) ||
          !valid.ok ||
          valid.sanitizedCall?.name !== "awakened_mimic"
        )
          continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = candidates.get(targetId),
          origin = roles.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target) ||
          !origin ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== origin.component ||
          origin.component.role !== origin.role ||
          origin.component.camp !== origin.camp
        )
          continue;
        if (!learnAwakenedRole(owner.state, targetId, origin.role, day)) continue;
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_mimicked",
          payload: { actorId: owner.actorId, day, targetId, role: owner.state.learned!.role },
        });
        completed = true;
        break;
      }
      if (!completed && owner.isCurrent() && canAwakenedMimic(owner.state, day)) {
        if (targets(ctx, owner.actorId, true).size)
          throw new Error("awakened_mimic_valid_action_missing");
        closeAwakenedMimic(owner.state, day);
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_mimic_skipped",
          payload: { actorId: owner.actorId, day },
        });
      }
    }
  },
};

const skillStage: NightStageHandler = {
  id: "awakened_skill",
  priority: 650,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const bound = bindAwakenedSkill(owner, day),
        skill = bound?.skill;
      if (!bound || !skill || skill.kind === "wolf") continue;
      const tool: ToolName = skill.kind === "poison" ? "awakened_poison" : "awakened_guard";
      const current = () => bound.isCurrent() && awakenedSkillForNight(owner.state, day) === skill;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, [tool], {
            stage: "awakened_skill",
            requiresAction: false,
            action_failure_policy: "error",
            allow_fallback: false,
            ...retry(attempt),
          }),
        );
        if (!current()) break;
        if (action === null) {
          if (!skipAwakenedSkill(owner.state, day)) break;
          recordAwakenedNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_skill_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== tool) continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || !valid.sanitizedCall) continue;
        const call = valid.sanitizedCall;
        if (call.name !== "awakened_poison" && call.name !== "awakened_guard") continue;
        const targetId = call.args.target_id,
          target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (call.name === "awakened_poison" && skill.kind === "poison" && target) {
          if (!useAwakenedPoison(owner.state, day)) break;
          (ctx.state.poisonClaims ??= []).push(
            originalPoisonIntent(
              {
                source: owner.life,
                target,
                isCurrent: () => bound.isCurrent(true),
              },
              {
                family: "awakened",
                day,
                stage: "awakened_skill",
                actorLife: owner.life,
                requestedTargetId: targetId,
                abilityId: "learned:awakened",
              },
            ),
          );
          ctx.ensureMarks(target.id).add(StatusMark.PoisonMark);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_poison_used",
            payload: { actorId: owner.actorId, day, targetId: target.id },
          });
        } else if (call.name === "awakened_guard" && skill.kind === "guard") {
          if (!chooseAwakenedGuard(owner.state, targetId, day)) continue;
          if (target)
            effects(ctx).shields.push(
              awakenedNightIntent(
                "awakened-shield",
                {
                  actorId: owner.actorId,
                  target,
                  isCurrent: () => bound.isCurrent(true),
                },
                {
                  family: "awakened",
                  day,
                  stage: "awakened_skill",
                  actorLife: owner.life,
                  requestedTargetId: targetId,
                  abilityId: "learned:awakened",
                },
              ),
            );
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_guard_chosen",
            payload: { actorId: owner.actorId, day, targetId },
          });
        } else continue;
        recordAwakenedNightCommit(ctx.world, day);
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("awakened_skill_valid_action_missing");
    }
  },
};

const attackStage: NightStageHandler = {
  id: "awakened_attack",
  priority: 660,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const bound = bindAwakenedSkill(owner, day);
      if (bound?.skill.kind !== "wolf") continue;
      const effectCurrent = () => bound.isCurrent() && canAwakenedKnife(owner.role, ctx.world);
      const current = () => effectCurrent() && canAwakenedExtraKnife(owner.state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, ["awakened_attack"], {
            stage: "awakened_attack",
            requiresAction: false,
            action_failure_policy: "error",
            allow_fallback: false,
            ...retry(attempt),
          }),
        );
        if (!current()) break;
        let targetId: number | null = null;
        if (action !== null) {
          if (action.name !== "awakened_attack") continue;
          const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
            phase: Phase.Night,
            day,
          });
          if (!current() || !valid.ok || valid.sanitizedCall?.name !== "awakened_attack") continue;
          targetId = valid.sanitizedCall.args.target_id;
        }
        const target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (!chooseAwakenedAttack(owner.state, targetId, day)) break;
        if (target)
          effects(ctx).attacks.push(
            awakenedNightIntent(
              "awakened-attack",
              { actorId: owner.actorId, target, isCurrent: effectCurrent },
              {
                family: "awakened",
                day,
                stage: "awakened_attack",
                actorLife: owner.life,
                requestedTargetId: targetId,
                abilityId: "learned:awakened",
              },
            ),
          );
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_attack_chosen",
          payload: { actorId: owner.actorId, day, targetId },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("awakened_attack_valid_action_missing");
    }
  },
};

const activationStage: NightStageHandler = {
  id: "awakened_activation",
  priority: 900,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const learned = owner.state.learned;
      if (!learned || learned.activationNight !== null || !owner.isCurrent()) continue;
      let abilityId: string | undefined;
      if (learned.skill.kind === "inspection") {
        if (
          allNightAbilities(owner.role).some(
            (ability) => ability.kind === "role_check" && ability.source.kind === "native",
          ) ||
          retiredNightAbilityIds(owner.role).some((id) => id.startsWith("native:role_check"))
        )
          throw new Error("awakened_mirror_native_binding_conflict");
        installNativeAbility(owner.role, "role_check", {
          policy: "mirror",
          lastTarget: null,
          lastDay: null,
          history: [],
        });
        const ability = findNightAbility(owner.role, "role_check")!;
        setNightAbilityStartDay(ability, day + 1);
        abilityId = ability.id;
      }
      if (
        !owner.isCurrent() ||
        owner.state.learned !== learned ||
        !activateAwakenedLearning(owner.state, day, abilityId)
      )
        throw new Error("awakened_activation_commit_invalid");
      recordAwakenedNightCommit(ctx.world, day);
      ctx.events.push({
        timestamp: Date.now(),
        type: "awakened_ready",
        payload: {
          actorId: owner.actorId,
          activationNight: day,
          activeFromNight: day + 1,
          role: learned.role,
        },
      });
    }
  },
};

export const AWAKENED_NIGHT_STAGES = [
  openingStage,
  mimicStage,
  skillStage,
  attackStage,
  activationStage,
];

/**
 * 负责有限猎魔人板的原生女巫行动、真实用药交付及夜间来源封存。
 * 输入为原 World、夜号、刀口、网关与 Provider；输出为行动回执、已付救／毒交付及封存来源。
 * 两条原毒分支在原 claim 创建位置附加 sourced intent，复用已捕获 source/target/day。
 * 保留瓶数付款、commit、交付缓存、事实发布与关闭的原次序；后续失败不回滚已提交前缀。
 * 新来源 metadata 与 life 句柄仅运行时使用，不加入事件、player DTO 或归档字段。
 */
import {
  COMPONENT,
  Phase,
  PotionType,
  StatusMark,
  settleRequestDelivery,
  type ActionProvider,
  type GameEvent,
  type World,
} from "../../../../core";
import {
  StatusMarksComponent,
  statusMarkSnapshot,
} from "../../../../core/domain/components/status_marks";
import {
  captureNightLife,
  originalPoisonIntent,
  type NightPoisonClaim,
} from "../../../../core/domain/night_effects";
import type { ActionRequestFactoryConstructorPort } from "../../../../core/domain/actions";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { type NightAbility } from "../abilities";
import { recordNightAbilityUse } from "../ability_changes";
import {
  openDemonWitchTurnFrame,
  demonHunterFreezeDay,
  demonWitchRequiredThisNight,
} from "./authority";
import {
  bindDemonWitchRequest,
  demonWitchRequestCurrent,
  readDemonPotionTool,
  demonWitchRequestTargetCurrent,
  demonWitchMarksSafe,
} from "./native_potion_requests";
import {
  captureDemonNativePoison,
  commitDemonNativePoison,
  freezeDemonNightSources,
  type DemonNightSources,
} from "./native_poison";
import {
  openNativePoisonContribution,
  commitNativePoisonContribution,
  sealNativePoisonContribution,
  lateUnknownPoisonContribution,
  type NativePoisonContributions,
} from "./poison_contribution";

import {
  openNativeHealContribution,
  commitNativeHealContribution,
  sealNativeHealContribution,
  lateUnknownHealContribution,
  type NativeHealContributions,
} from "./heal_contribution";
/** 已付救药的运行交付；原生命查询与贡献封存回调不能进入玩家 DTO 或归档。 */
interface DeliveredDemonHeal {
  readonly claim: Readonly<NightPoisonClaim>;
  readonly lateUnknown: () => boolean;
  readonly sealContribution: () => Readonly<NativeHealContributions>;
}
const deliveredHeals = new WeakMap<World, Map<number, Readonly<DeliveredDemonHeal>>>();
/**
 * 已付原生毒的运行交付；proof 仅在毒向猎魔人且原生免疫来源被登记时存在。
 * 普通原生毒仍保留 claim 与独立贡献；null proof 不表示没有付款或没有毒来源。
 */
export interface DeliveredDemonPoison {
  readonly proof: object | null;
  readonly claim: Readonly<NightPoisonClaim>;
  readonly lateUnknown: () => boolean;
  readonly sealContribution: () => Readonly<NativePoisonContributions>;
}
const nativeAddMark = StatusMarksComponent.prototype.add;
const delivered = new WeakMap<World, Map<number, Readonly<DeliveredDemonPoison> | null>>();
/**
 * 私有 token 对应的唯一封存账本，绑定原 World 与夜号。贡献在普通伤害清标记前捕获；
 * frozen 只在底层来源冻结成功后置位，后续构造失败也不恢复该 token 的可用性。
 */
interface Sealed {
  world: World;
  day: number;
  poison: Readonly<DeliveredDemonPoison> | null;
  contributions: Readonly<NativePoisonContributions> | null;
  heal: Readonly<DeliveredDemonHeal> | null;
  healContributions: Readonly<NativeHealContributions> | null;
  frozen: boolean;
}
const sealedSources = new WeakMap<object, Sealed>();
const sealedNights = new WeakMap<World, Set<number>>();
/** 本次行动交付结果；used 只区分用药与放弃，poison 不承载救药回执。 */
export interface DemonWitchTurnResult {
  readonly poison: Readonly<DeliveredDemonPoison> | null;
  readonly used: boolean;
}
/** 原有限猎魔人板中唯一原生女巫的执行路径；await 后复验原请求与目标，最终关闭交付窗口。 */
export async function executeDemonWitchTurn(input: {
  world: World;
  gateway: ToolGateway;
  events: GameEvent[];
  provider: ActionProvider;
  day: number;
  wolfTarget: number | null;
  /** 只在原 new 点读取；原 frame 开启／夜复位已发生，依赖不授予用药资格。 */
  construction: { readonly requestFactory: ActionRequestFactoryConstructorPort };
}): Promise<Readonly<DemonWitchTurnResult>> {
  const { world, gateway, events, provider, day, wolfTarget } = input,
    frame = openDemonWitchTurnFrame(world);
  if (!frame || frame.day !== day) throw new Error("demon_hunter_native_witch_unavailable");
  const ability = frame.ability as NightAbility<"potion">,
    scope = Object.freeze({});
  let closed = false;
  if (!world.entityIds().every((id) => demonWitchMarksSafe(world, id)))
    throw new Error("demon_hunter_native_marks_invalid");
  // frame 开启和 marks 检查先完成；原 new／bind 在 try 外，失败保留复位前缀，不加新的 finally。
  const request = new input.construction.requestFactory(world, events, day).create({
    phase: Phase.Night,
    actorId: frame.witchId,
    allowedTools: ["use_potion"],
    stage: "witch",
    requiresAction: true,
    summary: { key: "request.summary.night_action" },
    context: {
      ability_id: "native:potion",
      allow_fallback: false,
      action_failure_policy: "error",
      ...(ability.state.heal > 0 ? { wolf_target: wolfTarget } : {}),
    },
  });
  bindDemonWitchRequest(
    world,
    request,
    scope,
    () => !closed && frame.isCurrent(),
    frame.targetCurrent,
  );
  const authorized = () => demonWitchRequestCurrent(world, request);
  try {
    if (!authorized()) throw new Error("demon_hunter_native_witch_revoked");
    const raw = await provider.getAction(request);
    if (!authorized()) throw new Error("demon_hunter_native_witch_revoked");
    const call = readDemonPotionTool(raw);
    if (!call || !demonWitchRequestTargetCurrent(world, request, call.args.target_id))
      throw new Error("demon_hunter_native_witch_invalid");
    const candidateMarks = world.getComponent(call.args.target_id, COMPONENT.StatusMarks);
    if (
      candidateMarks &&
      (!statusMarkSnapshot(candidateMarks, StatusMark.PoisonMark) ||
        Object.getPrototypeOf(candidateMarks) !== StatusMarksComponent.prototype ||
        Object.getOwnPropertyDescriptor(candidateMarks, "has"))
    )
      throw new Error("demon_hunter_native_marks_invalid");
    const checked = gateway.validateAndSanitize(world, frame.witchId, call, {
      phase: Phase.Night,
      day,
      abilityId: "native:potion",
      deferOperation: true,
    });
    if (
      !checked.ok ||
      !checked.sanitizedCall ||
      !authorized() ||
      !demonWitchRequestTargetCurrent(world, request, call.args.target_id)
    )
      throw new Error("demon_hunter_native_witch_invalid");
    const targetId = call.args.target_id,
      potion = call.args.potion_type;
    const source = captureNightLife(world, frame.witchId),
      target = captureNightLife(world, targetId);
    if (!source || !target) throw new Error("demon_hunter_native_witch_revoked");
    Object.freeze(source);
    Object.freeze(target);
    let poison: Readonly<DeliveredDemonPoison> | null = null;
    const native =
      potion === PotionType.Poison && targetId === frame.demonId
        ? captureDemonNativePoison(world, frame.witchId, ability, targetId)
        : null;
    if (potion === PotionType.Poison && targetId === frame.demonId && !native)
      throw new Error("demon_hunter_native_poison_unavailable");
    let marks = world.getComponent(targetId, COMPONENT.StatusMarks);
    if (potion !== PotionType.None && !marks) {
      marks = new StatusMarksComponent();
      world.addComponent(targetId, COMPONENT.StatusMarks, marks);
    }
    const contribution =
      potion === PotionType.Poison && marks
        ? openNativePoisonContribution(world, targetId, marks)
        : null;
    const healContribution =
      potion === PotionType.Heal && marks
        ? openNativeHealContribution(world, targetId, marks)
        : null;
    // 先登记使用、写标记及扣瓶，再由 frame 核对真实库存提交；失败不伪造付款回滚。
    recordNightAbilityUse(ability, day, potion !== PotionType.None);
    if (potion !== PotionType.None) {
      nativeAddMark.call(
        marks!,
        potion === PotionType.Heal ? StatusMark.HealMark : StatusMark.PoisonMark,
      );
      ability.state[potion]--;
      ability.state[potion === PotionType.Heal ? "healUsedThisNight" : "poisonUsedThisNight"] =
        true;
    }
    if (!frame.commit(potion)) throw new Error("demon_hunter_native_witch_commit_failed");
    // frame 已提交后先登记真实贡献；随后 proof、交付或事实发布失败仍保留这段已付前缀。
    if (contribution) commitNativePoisonContribution(contribution);
    if (healContribution) {
      commitNativeHealContribution(healContribution);
      const heals = deliveredHeals.get(world) ?? new Map<number, Readonly<DeliveredDemonHeal>>();
      if (heals.has(day)) throw new Error("demon_hunter_native_witch_delivery_reentry");
      heals.set(
        day,
        Object.freeze({
          claim: Object.freeze({
            source,
            target,
            isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
          }),
          lateUnknown: () => lateUnknownHealContribution(healContribution),
          sealContribution: () => sealNativeHealContribution(healContribution),
        }),
      );
      deliveredHeals.set(world, heals);
    }
    if (native && contribution) {
      const proof = commitDemonNativePoison(native);
      if (!proof) throw new Error("demon_hunter_native_poison_commit_failed");
      poison = Object.freeze({
        proof,
        claim: Object.freeze(
          originalPoisonIntent(
            {
              source,
              target,
              isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
            },
            {
              family: "demon-witch",
              day,
              stage: "witch",
              actorLife: source,
              requestedTargetId: targetId,
              abilityId: "native:potion",
            },
          ),
        ),
        lateUnknown: () => lateUnknownPoisonContribution(contribution),
        sealContribution: () => sealNativePoisonContribution(contribution),
      });
    } else if (potion === PotionType.Poison) {
      // 普通原生毒不持有猎魔人免疫 proof；来源与后续独立毒贡献仍必须保留。
      poison = Object.freeze({
        proof: null,
        claim: Object.freeze(
          originalPoisonIntent(
            {
              source,
              target,
              isCurrent: () => frame.sourceCurrent() && frame.targetCurrent(targetId),
            },
            {
              family: "demon-witch",
              day,
              stage: "witch",
              actorLife: source,
              requestedTargetId: targetId,
              abilityId: "native:potion",
            },
          ),
        ),
        lateUnknown: () => lateUnknownPoisonContribution(contribution!),
        sealContribution: () => sealNativePoisonContribution(contribution!),
      });
    }
    const nights = delivered.get(world) ?? new Map<number, Readonly<DeliveredDemonPoison> | null>();
    if (nights.has(day)) throw new Error("demon_hunter_native_witch_delivery_reentry");
    nights.set(day, poison);
    delivered.set(world, nights);
    settleRequestDelivery(scope, true);
    safeRecordLogicOp({
      scope: "gateway",
      op: "validate_tool_call",
      actorId: frame.witchId,
      phase: Phase.Night,
      status: "ok",
      input: { tool: call.name, args: call.args },
    });
    events.push({
      timestamp: Date.now(),
      type: potion === PotionType.None ? "witch_potion_skipped" : "witch_potion_used",
      payload: {
        actorId: frame.witchId,
        targetId,
        potionType: potion,
      },
    } as GameEvent);
    return Object.freeze({ poison, used: potion !== PotionType.None });
  } finally {
    closed = true;
    settleRequestDelivery(scope, false);
  }
}

/** 在普通伤害清除标记前封存原交付贡献；返回仅本控制器登记的运行 token，同夜不得重封。 */
export function sealDeliveredDemonWitchSources(world: World, day: number): object {
  if (
    demonHunterFreezeDay(world) !== day ||
    (demonWitchRequiredThisNight(world) && !delivered.get(world)?.has(day))
  )
    throw new Error("demon_hunter_native_sources_missing");
  const seen = sealedNights.get(world) ?? new Set<number>();
  if (seen.has(day)) throw new Error("demon_hunter_native_sources_already_sealed");
  const poison = delivered.get(world)?.get(day) ?? null;
  const contributions = poison?.sealContribution() ?? null;
  const heal = deliveredHeals.get(world)?.get(day) ?? null,
    healContributions = heal?.sealContribution() ?? null;
  const token = Object.freeze({});
  sealedSources.set(token, {
    world,
    day,
    poison,
    contributions,
    heal,
    healContributions,
    frozen: false,
  });
  seen.add(day);
  sealedNights.set(world, seen);
  return token;
}
/** 冻结后的来源结果；救／毒覆盖只重算本控制器涉及的目标，不替代其它独立来源。 */
export interface DeliveredDemonNightSources extends DemonNightSources {
  readonly poisonOverrides: readonly Readonly<{ targetId: number; poison: boolean }>[];
  readonly healOverrides: readonly Readonly<{ targetId: number; heal: boolean }>[];
}
/**
 * 完整来源只取真实控制器与私有 token，不从 Tape 事实或调用方 metadata 恢复授权。
 * 先查询原来源当前性及迟到的独立贡献，再冻结底层毒／狩猎；底层成功后立即消费封存账本。
 * 猎魔人的原生毒免疫只抵消该原生贡献，unknown 或迟到独立毒继续参与目标的最终覆盖。
 */
export function freezeDeliveredDemonNightSources(
  world: World,
  token: object,
  faultId: string | null = null,
): Readonly<DeliveredDemonNightSources> {
  const sealed = sealedSources.get(token),
    day = demonHunterFreezeDay(world);
  if (!sealed || sealed.world !== world || sealed.day !== day || sealed.frozen)
    throw new Error("demon_hunter_native_sources_invalid");
  const poison = sealed.poison,
    contributions = sealed.contributions;
  const originalSourceCurrent = poison?.claim.isCurrent?.() === true;
  const lateUnknown = poison?.lateUnknown() ?? false;
  const healCurrent = sealed.heal?.claim.isCurrent?.() === true,
    lateHeal = sealed.heal?.lateUnknown() ?? false;
  const result = freezeDemonNightSources(world, poison?.proof ? [poison.proof] : [], faultId);
  sealed.frozen = true;
  const immunity =
    !!poison?.proof &&
    contributions?.native === true &&
    originalSourceCurrent &&
    result.poisonImmunities.length === 1;
  return Object.freeze({
    hunt: result.hunt,
    healOverrides: Object.freeze(
      sealed.heal && sealed.healContributions
        ? [
            Object.freeze({
              targetId: sealed.heal.claim.target.id,
              heal:
                sealed.healContributions.unknown ||
                lateHeal ||
                (sealed.healContributions.native && healCurrent),
            }),
          ]
        : [],
    ),
    poisonImmunities: Object.freeze(immunity ? [...result.poisonImmunities] : []),
    poisonOverrides: Object.freeze(
      poison && contributions
        ? [
            Object.freeze({
              targetId: poison.claim.target.id,
              poison:
                contributions.unknown ||
                lateUnknown ||
                (contributions.native && originalSourceCurrent && !immunity),
            }),
          ]
        : [],
    ),
  });
}

/**
 * 负责摄梦人对当前能力及原目标生命的行动。
 * 输入为查询给出的 actor、夜请求和合法梦目标；输出保留历史与有来源梦保护。
 * 具体状态写入和共享 use 命令仍在原 commit 位置，资格／事实顺序不变。
 * 本阶段不执行死亡波或刷新已失效目标，也不回滚已付历史。
 */
import { DREAMER_STATE_SLOT } from "./ports";
import { isRadiantEclipseBoard, captureRadiantPaidEffect } from "../radiant_eclipse/night_frame";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Phase } from "../../../../core/domain/model";
import type { NightStageHandler } from "../../stages/night/contracts";
import { recordNightAbilityUse } from "../ability_changes";
import { captureNightAbilityScope } from "../ability_scope";
import { markDreamNightCommitted } from "./night_frame";
import { dreamNightLinksForAppend } from "./night-links";

export const DREAMER_NIGHT_STAGE: NightStageHandler = {
  id: "dreamer_action",
  priority: 150,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const { actorId, ability } of ctx.nightActors.actors("dream", day)) {
      if (!ctx.isCurrent()) return;
      const scope = captureNightAbilityScope(
        ctx.world,
        actorId,
        ability,
        day,
        () => ctx.isCurrent() && ctx.currentDay() === day,
      );
      if (!scope?.isEligible()) continue;
      const actorLife = scope.life.life,
        actorVersion = scope.life.version,
        state = ability.state;
      const targets = new Map(
        ctx.world
          .getAliveEntityIds()
          .filter((id) => id !== actorId)
          .map((id) => {
            const life = ctx.world.getComponent(id, COMPONENT.Alive)!;
            return [id, { life, version: aliveLifeVersion(life) }] as const;
          }),
      );
      if (targets.size === 0) continue;
      let applied = false;
      const current = () => scope.isEligible();
      for (let attempt = 1; attempt <= 3; attempt++) {
        if (!current()) {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_scope_stale");
          break;
        }
        const request = ctx.makeRequest(actorId, ["dream"], {
          stage: "dreamer",
          ability_id: ability.id,
          ...(attempt === 1 ? {} : { retry_attempt: attempt - 1, retry_max: 2 }),
        });
        if (!current()) {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_scope_stale");
          break;
        }
        const action = await ctx.actionProvider.getAction(request);
        if (!current()) {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_scope_stale");
          break;
        }
        if (action?.name !== "dream") {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_action_missing");
          continue;
        }
        const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
          abilityId: ability.id,
        });
        if (!current()) {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_scope_stale");
          break;
        }
        if (!validated.ok || validated.sanitizedCall?.name !== "dream") {
          if (isRadiantEclipseBoard(ctx.world))
            throw new Error("radiant_eclipse_dream_action_invalid");
          continue;
        }
        const targetId = validated.sanitizedCall.args.target_id,
          target = targets.get(targetId);
        if (
          !target ||
          ctx.world.getComponent(targetId, COMPONENT.Alive) !== target.life ||
          !target.life.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.life) !== target.version
        )
          continue;
        const consecutive = state.lastDay === day - 1 && state.lastTarget === targetId;
        DREAMER_STATE_SLOT.allowedWrites.recordDreamSelection(state, targetId, day);
        recordNightAbilityUse(ability, day, true);
        markDreamNightCommitted(ctx.world, day);
        applied = true;
        // 历史、次数与开夜提交已经落下；先取本族同数组的 push，再构造原生命／已付效果条目。
        dreamNightLinksForAppend(ctx.state).push({
          actorId,
          targetId,
          day,
          isCurrent: captureRadiantPaidEffect(ctx.world, day, actorId, ability, targetId),
          consecutive,
          protectionPolicy: state.protectionPolicy,
          actorLife,
          actorVersion,
          targetLife: target.life,
          targetVersion: target.version,
          ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "dream_applied",
          payload: {
            actorId,
            targetId,
            day,
            consecutive,
            ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
          },
        });
        break;
      }
      if (
        !applied &&
        current() &&
        [...targets].some(
          ([id, target]) =>
            ctx.world.getComponent(id, COMPONENT.Alive) === target.life &&
            target.life.alive &&
            target.version !== undefined &&
            aliveLifeVersion(target.life) === target.version,
        )
      )
        throw new Error("dream_required_action_missing");
    }
  },
};

/**
 * 负责摄梦人原生状态槽访问及 target/day/history 的具体写入。
 * 输入为原角色、能力或已捕获状态和接受目标；输出保留安装复制、原槽引用与部分写入顺序。
 * 数据／只读形状来自 contract；连续目标、租约、use 计数、梦效果和事实仍在原 caller 位置。
 * 本 owner 不制造状态镜像、回滚已付资源或新增资格重检。
 */
import type { DreamerState, DreamerReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "@ai-werewolf-arena/game-contract";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../prepared-native-install";

/** 初始化只复制原 JSON 并提交同一原生库存；连续目标和保护资格不是安装校验。 */
export function setDreamerState(roleComp: RoleComponent, state: DreamerState): DreamerReadState {
  return commitPreparedNativeAbility(roleComp, "dream", DREAMER_STATE_SLOT.create(state));
}

export function getDreamerState(
  roleComp: RoleComponent,
  abilityId?: string,
): DreamerReadState | undefined {
  return findNightAbility(roleComp, "dream", abilityId)?.state;
}

/** 目标／scope 检查、次数、梦效果与事实仍在 caller；history 失败不回滚已写 target/day。 */
export function recordDreamSelection(
  state: DreamerReadState,
  targetId: EntityId,
  day: number,
): void {
  // target/day 先落原槽，再读取 history 并 push；后段失败保留两项已写前缀。
  (state as DreamerState).lastTarget = targetId;
  (state as DreamerState).lastDay = day;
  (state as DreamerState).history.push({ day, targetId });
}

/** 原 stringify callee 先于 state／protectionPolicy 读取；只编码既有 scope 身份。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"dream">): string {
  return JSON.stringify([ability.state.protectionPolicy]);
}

/** JSON 创建／schema 沿用旧接受集合；读同一库存，明确写入不制造新 lease 或状态镜像。 */
export const DREAMER_STATE_SLOT = Object.freeze({
  create: copyAbilityData<DreamerState>,
  schema: copyAbilityData<DreamerState>,
  install: setDreamerState,
  get: getDreamerState,
  allowedWrites: Object.freeze({ recordDreamSelection }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 负责原生 Pair 完整 slot 契约、安装与已审查的查验写入前缀。
 * 输入为原角色或 authority 捕获的槽和已验证下一历史；输出保留 pairSeer/native 同状态引用。
 * 按原顺序写状态 JSON、提交共享 use metadata、再写 ability JSON；authority 随后才提交租约。
 * 安装槽的 LHS 仍先于原能力复制调用；不读时 clone、替换存储状态、退款或吞掉部分写入错误。
 * create/schema、唯一追加写命令、checkpoint codec 与别名／已提交 JSON 失效规则实际统一于本 owner。
 * codec 只在原 JSON 位置编码已验证数据，不把重新校验提前到付款或篡改普通 private 扩展键。
 * 规则边界见 docs/rules/awa-fragrant-pair-seer-twelve-v1.md。
 */
import type { PairSeerState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import { type NightAbilityReadView } from "../abilities";
import { installNativeAbility, recordNightAbilityUse } from "../ability_changes";
import { freshPairSeerState, readPairSeerState } from "./state";
import { assertWritable, plainJson, write } from "./owned-state-data";

/** 捕获的状态／能力引用与已提交 JSON 保留在同一个原 Fragrant owner 上。 */
export interface PairStateSlot {
  readonly pairState: PairSeerState;
  readonly pairAbility: NightAbilityReadView<"pair_check">;
  pairAbilityJson: string;
  pairJson: string;
}

/** 安装先读取赋值左侧 privateState，再调用原能力安装函数。 */
export function installPairStateSlot(role: RoleComponent): void {
  (role.privateState as { pairSeer: NightAbilityReadView<"pair_check">["state"] }).pairSeer =
    installNativeAbility(role, "pair_check", PAIR_STATE_SLOT_CONTRACT.create());
}

/** 调用方已在原位置检查当前性与活跃能力；此处只拥有已审查写入前缀。 */
export function commitPairStateSlot(slot: PairStateSlot, next: PairSeerState, day: number): void {
  assertWritable(slot.pairAbility, slot.pairAbility);
  write(slot.pairState, next);
  slot.pairJson = PAIR_STATE_SLOT_CONTRACT.checkpoint.encode(next);
  recordNightAbilityUse(slot.pairAbility, day, true);
  slot.pairAbilityJson = plainJson(slot.pairAbility)!;
}

/** 只描述已有 Pair owner 的原引用；不复制角色、能力或第二份状态。 */
export interface PairStateSlotProof extends PairStateSlot {
  readonly seer: { readonly privateState: object };
  readonly abilities: unknown;
  readonly pairSource: NightAbilityReadView<"pair_check">["source"];
}

/** 使用 authority 原 descriptor reader，保持同一 invalid sentinel 及所有参数读取顺序。 */
type OwnDataReader = (value: unknown, key: PropertyKey) => unknown;
function pairAliasesCurrent(slot: PairStateSlotProof, own: OwnDataReader): boolean {
  return (
    own(slot.seer.privateState, "pairSeer") === slot.pairState &&
    own(slot.seer.privateState, "abilities") === slot.abilities &&
    plainJson(slot.pairAbility) === slot.pairAbilityJson &&
    slot.pairAbility.source === slot.pairSource &&
    own(slot.abilities, slot.pairAbility.id) === slot.pairAbility &&
    slot.pairAbility.state === slot.pairState
  );
}
function pairDataCurrent(slot: PairStateSlot): boolean {
  // 此检查仍在 Fragrant schema 检查之后；JSON callee 先于数据／JSON getter 读取。
  return JSON.stringify(readPairSeerState(slot.pairState)) === slot.pairJson;
}

/**
 * Pair 本族完整贡献：schema 与 factory 是原函数，允许写入口仅为实际 append commit。
 * snapshot decoder 接延迟 JSON 字段，保 JSON.parse 方法查找在原字段 getter 之前。
 * 失效检查只验证别名和已提交数据；资格、原生命、租约及完整／失败模式仍由 authority 控制。
 */
export const PAIR_STATE_SLOT_CONTRACT = Object.freeze({
  create: freshPairSeerState,
  schema: readPairSeerState,
  allowedWrites: Object.freeze({ appendCheck: commitPairStateSlot }),
  checkpoint: Object.freeze({
    encode: (state: PairSeerState): string => JSON.stringify(state),
    decode: (readJson: () => string): PairSeerState => JSON.parse(readJson()) as PairSeerState,
  }),
  invalidations: Object.freeze({
    aliasesCurrent: pairAliasesCurrent,
    dataCurrent: pairDataCurrent,
  }),
});

/**
 * 负责守卫基于捕获能力及原生命的目标选择。
 * 输入为夜上下文、资格查询和已验证守护工具；输出保留 lastTarget、use metadata 及原守护贡献。
 * 原贡献 owner 保留已付效果有效性，不能把它转移给替换的印记组件。
 * 查询、请求、资格、状态命令与事实发布仍按原位置执行，不增加重复目标重检或退款。
 */
import { GUARD_STATE_SLOT } from "./ports";
/** 文件说明：守卫夜间阶段处理。 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { RoleComponent } from "../../../../core/domain/components/role";
import { Phase, Role, StatusMark } from "../../../../core/domain/model";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { NightStageHandler } from "../../stages/night/contracts";
import { getGuardState } from "./ports";
import { activeNightAbility } from "../abilities";
import { recordNightAbilityUse } from "../ability_changes";
import { captureNightAbilityScope } from "../ability_scope";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import { recordOwnNightAction, luckyTargetAllowed } from "../night_action_history";

const guardActionStage: NightStageHandler = {
  id: "guard_action",
  priority: 300,
  async execute(ctx): Promise<void> {
    if (ctx.nativeNightFailure.usesDemonController()) {
      const { executeDemonNativeNight } = await ctx.nativeNightEffects.loadSealedNightController();
      await executeDemonNativeNight(ctx, "guard");
      return;
    }
    for (const { actorId: guardId, ability } of ctx.nightActors.actors("guard", ctx.currentDay())) {
      if (ability.activation === "lucky" || ability.activation === "black_market") continue;
      ctx.nativeNightFailure.assertNativeActor(guardId, Role.Guard);
      const day = ctx.currentDay(),
        scope = captureNightAbilityScope(
          ctx.world,
          guardId,
          ability,
          day,
          () => ctx.isCurrent() && ctx.currentDay() === day,
        );
      if (!scope?.isEligible()) continue;
      const targets = new Map(
        ctx.world.getAliveEntityIds().map((id) => [id, captureNightLife(ctx.world, id)]),
      );
      if (
        !ctx.world.getAliveEntityIds().includes(guardId) ||
        activeNightAbility(
          ctx.world.getComponent(guardId, COMPONENT.Role),
          "guard",
          ctx.currentDay(),
          ability.id,
        ) !== ability
      )
        continue;
      const req = ctx.makeRequest(guardId, ["guard"], { stage: "guard", ability_id: ability.id });
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("guard");
        continue;
      }
      const action = await ctx.actionProvider.getAction(req);
      if (!ctx.isCurrent()) return;
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("guard");
        continue;
      }
      if (action?.name !== "guard") {
        ctx.nativeNightFailure.actionMissing("guard");
        continue;
      }

      const result = ctx.toolGateway.validateAndSanitize(ctx.world, guardId, action, {
        phase: Phase.Night,
        day: ctx.currentDay(),
        abilityId: ability.id,
      });
      if (!ctx.isCurrent()) return;
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("guard");
        continue;
      }
      if (!result.ok || !result.sanitizedCall) {
        ctx.nativeNightFailure.actionInvalid("guard");
        safeRecordLogicOp({
          scope: "phase_pipeline",
          op: "guard_action_rejected",
          actorId: guardId,
          phase: Phase.Night,
          status: "rejected",
        });
        continue;
      }
      const currentRole = ctx.world.getComponent(guardId, COMPONENT.Role);
      if (!activeNightAbility(currentRole, "guard", ctx.currentDay(), ability.id)) continue;
      const abstain = result.sanitizedCall.args.abstain === true;
      const targetId = abstain ? null : result.sanitizedCall.args.target_id;
      const target = targetId === null ? null : targets.get(targetId);
      if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
      if (
        !abstain &&
        targetId !== null &&
        !luckyTargetAllowed(ctx.world, guardId, ability, day, "guard", targetId)
      )
        continue;
      if (!abstain && targetId !== null) {
        const receipt = ctx.nativeNightTargets.reflectedTarget(
          () => day,
          () => guardId,
          () => targetId,
          "guard",
        );
        if (receipt && (ability.source.kind !== "native" || ability.source.role !== Role.Guard))
          throw new Error("time_consort_guard_source_invalid");
        ctx.nativeNightEffects.commitReflectedTarget(receipt, day, guardId, "guard");
        const marks = ctx.ensureMarks(receipt?.effectiveId ?? targetId);
        marks.add(StatusMark.GuardMark);
        (ctx.state.guardClaims ??= []).push({ target: receipt?.scope ?? target!, marks });
      }
      ctx.events.push({
        timestamp: Date.now(),
        type: "guard_applied",
        payload: {
          actorId: guardId,
          ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
          abstain,
          targetId,
        },
      });
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "guard_applied",
        actorId: guardId,
        phase: Phase.Night,
        status: "ok",
        output: { abstain, target_id: targetId },
      });

      const role = ctx.world.getComponent(guardId, COMPONENT.Role);
      const guardState = role ? getGuardState(role, ability.id) : undefined;
      if (guardState) {
        GUARD_STATE_SLOT.allowedWrites.recordGuardTarget(guardState, targetId);
      }
      recordNightAbilityUse(ability, ctx.currentDay(), !abstain);
      ctx.nativeNightEffects.recordModifierTarget(day, guardId, "guard", () => targetId);
      if (!abstain && targetId !== null)
        recordOwnNightAction(ctx.world, guardId, day, "guard", targetId, false);
    }
  },
};

/** 守卫夜间阶段列表。 */
export const GUARD_NIGHT_STAGES: NightStageHandler[] = [guardActionStage];

/**
 * 负责守卫普通／受赠能力的原生安装、同槽读取与上次目标字段写入。输入为原角色、
 * 状态或已验证受赠目标；输出保持 nullable lastTarget 和 repeatPolicy，不复制读到的库存。
 * 受赠写入先捕获左侧 ability.state，再读取 target.id getter；普通写入只修改已捕获字段，
 * 守护印记、映射目标、次数及事实发表仍由 caller 按原顺序负责。JSON 复制不扩大旧拒绝集合；
 * prepared owner 安装原库存，政策身份字节仅作既有失效检查，不新增 lease 或档案形状。
 */
import type { GuardState, GuardReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "@ai-werewolf-arena/game-contract";

import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../prepared-native-install";

export function setGuardState(roleComp: RoleComponent, state: GuardState): GuardReadState {
  return commitPreparedNativeAbility(roleComp, "guard", GUARD_STATE_SLOT.create(state));
}

export function getGuardState(
  roleComp: RoleComponent,
  abilityId?: string,
): GuardReadState | undefined {
  return findNightAbility(roleComp, "guard", abilityId)?.state;
}

/** caller 保持原效果／发表和能力次数边界，此处只写捕获的目标字段。 */
export function recordGuardTarget(state: GuardReadState, targetId: EntityId | null): void {
  (state as { lastTarget: EntityId | null }).lastTarget = targetId;
}

/** 左侧先捕获原 state，再读取 target.id getter；后段失败仍保留原已提交前缀。 */
export function recordRecipientGuardTarget(
  ability: import("../abilities").NightAbilityReadView<"guard">,
  target: { readonly id: EntityId },
): void {
  const state = ability.state as { lastTarget: EntityId | null };
  state.lastTarget = target.id;
}

/** 原 JSON callee 先于全部状态字段读取；只迁政策身份字节，不新增 payload snapshot 或失效租约。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"guard">): string {
  return JSON.stringify([ability.state.repeatPolicy]);
}

/**
 * 本族完整契约引用原 JSON 复制函数和具体有序写入；create／schema 不改变旧接受集合。
 * install／get 与 caller 都消费同一实例库存，metadata 和 lease 保留唯一原所有者。
 * policyIdentity 是旧失效身份字节；checkpoint 归档并不调用新验证或改变原 privateState 形状。
 */
export const GUARD_STATE_SLOT = Object.freeze({
  create: copyAbilityData<GuardState>,
  schema: copyAbilityData<GuardState>,
  install: setGuardState,
  get: getGuardState,
  allowedWrites: Object.freeze({
    recordGuardTarget,
    recordRecipientGuardTarget,
  }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 负责纯白少女与狼巫各自原生角色查验政策。
 * 输入为共享只读查询后的当前 actor、合法目标和验证行动；输出保留历史及既定攻击效果。
 * 三个状态读取与历史追加委托 RoleInspection 具体 writer，use 委托实例 owner，仍在原位置。
 * 不合并阵营／角色查验、失败语义或阶段顺序，不引入最终目标复检。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { DeathCause } from "../../../../core/domain/deaths";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";

import { recordNightAbilityUse } from "../ability_changes";
import { captureNightAbilityScope } from "../ability_scope";
import { resolveInspection } from "../inspection";
import { ROLE_INSPECTION_STATE_SLOT } from "../role_inspection/ports";
import { recordRoleInspectionNightCommit } from "../role_inspection/night_scope";
import { pureWhiteInspectionTargets } from "./rules";

async function execute(ctx: NightStageContext, policy: "pure_white" | "wolf_witch"): Promise<void> {
  const day = ctx.currentDay();
  const expectedRole = policy === "pure_white" ? Role.PureWhiteGirl : Role.WolfWitch;
  for (const { actorId, ability } of ctx.nightActors.actors("role_check", day)) {
    if (!ctx.isCurrent()) return;
    if (roleInspectionPolicy(ability.state) !== policy) continue;
    if (ability.source.kind !== "native" || ability.source.role !== expectedRole) continue;
    const scope = captureNightAbilityScope(
      ctx.world,
      actorId,
      ability,
      day,
      () => ctx.isCurrent() && ctx.currentDay() === day,
    );
    if (!scope || scope.role.role !== expectedRole) continue;
    const current = () => scope.isEligible() && roleInspectionPolicy(ability.state) === policy;
    const close = (reason: "passed" | "no_targets") => {
      if (!current()) return;
      recordNightAbilityUse(ability, day, false);
      ctx.events.push({
        timestamp: Date.now(),
        type: "role_inspection_skipped",
        payload: { actorId, day, reason },
      });
      recordRoleInspectionNightCommit(ctx.world, day, ctx.isCurrent);
    };
    const targets = new Map(
      pureWhiteInspectionTargets(ctx.world, actorId, policy).map((id) => {
        const life = captureNightLife(ctx.world, id);
        const role = ctx.world.getComponent(id, COMPONENT.Role);
        return [id, { life, role, identity: role?.role, camp: role?.camp }] as const;
      }),
    );
    if (!current()) continue;
    if (!targets.size) {
      close("no_targets");
      continue;
    }
    const request = ctx.makeRequest(actorId, ["inspect_night_identity"], {
      stage: policy === "pure_white" ? "pure_white_girl" : "wolf_witch",
      requiresAction: true,
      ability_id: ability.id,
      action_failure_policy: "error",
      allow_fallback: false,
    });
    const action = await ctx.actionProvider.getAction(request);
    if (!current()) continue;
    if (action?.name !== "inspect_night_identity")
      throw new Error("pure_white_inspection_action_missing");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
      abilityId: ability.id,
    });
    if (!current()) continue;
    if (!validated.ok || validated.sanitizedCall?.name !== "inspect_night_identity")
      throw new Error("pure_white_inspection_action_invalid");
    const args = validated.sanitizedCall.args;
    if (args.abstain && args.target_id === null) {
      close("passed");
      continue;
    }
    const targetId = args.target_id;
    if (targetId === null) throw new Error("pure_white_inspection_target_invalid");
    const target = targets.get(targetId);
    const targetCurrent = () =>
      !!target?.life &&
      !!target.role &&
      livingNightLife(ctx.world, target.life) &&
      ctx.world.getComponent(targetId, COMPONENT.Role) === target.role &&
      target.role.role === target.identity &&
      target.role.camp === target.camp &&
      pureWhiteInspectionTargets(ctx.world, actorId, policy).includes(targetId);
    if (!targetCurrent()) throw new Error("pure_white_inspection_target_stale");
    const result = resolveInspection(ctx.world, targetId, "role", ctx.roleCatalog);
    if (!current()) continue;
    if (!result || !targetCurrent()) throw new Error("pure_white_inspection_target_stale");
    ROLE_INSPECTION_STATE_SLOT.allowedWrites.appendAbility(ability, targetId, day, result);
    recordNightAbilityUse(ability, day, true);
    ctx.events.push({
      timestamp: Date.now(),
      type: "role_inspected",
      payload: { actorId, targetId, day, result: { ...result } },
    });
    recordRoleInspectionNightCommit(ctx.world, day, ctx.isCurrent);
    if (
      day >= 2 &&
      (policy === "pure_white"
        ? target!.camp === Camp.Wolf
        : target!.identity === Role.PureWhiteGirl)
    ) {
      (ctx.state.inspectionAttacks ??= []).push({
        actorId,
        target: target!.life!,
        cause:
          policy === "pure_white" ? DeathCause.PureWhiteInspection : DeathCause.WolfWitchInspection,
        isCurrent: () =>
          scope.isOwnerCurrent() &&
          !ability.disabled &&
          !ability.deathExpired &&
