    players,
    maidId: maid[0]!.id,
    countId: count[0]!.id,
    knownWolves: Object.freeze(
      [...players.values()].filter((p) => p.kind === Role.Wolf).map((p) => p.id),
    ),
    eclipseState: new EclipseStateBinding(state as EclipseState, parsed),
    night: null,
    allowed: new Map(
