    b.night === n &&
    n.status !== "aborted" &&
    current(world, actor) &&
    current(world, target) &&
    own(actor.container, id as string) === ability &&
    own(ability, "id") === id &&
    own(ability, "kind") === kind &&
    own(ability, "state") === state &&
    own(ability, "source") === source &&
    sourceKeys.every((key, i) => own(source, key) === sourceValues[i]);
