/**
 * 输入为待安装庇护状态、原能力实例或已通过选择的 next 数据；输出为安装引用、独立读取结果或原槽的字段写入。
 * 庇护夜实例的完整状态契约与实际 payload 写入。prepare 只沿用原 JSON 复制，schema 则
 * 是原严格 reader，二者接受集合不同，不能在原生安装时增加拒绝。选择／投影返回独立数据。
 * 接受行动后仍先提交已支付庇护效果、再记 uses、最后写原 payload；Object.assign callee
 * 先于 ability.state getter，写失败保留已提交前缀。借用、过期已支付效果与首死归 frame。
 */
import type { ShelterState } from "@ai-werewolf-arena/game-contract";
import { copyAbilityData, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../prepared-native-install";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { createShelterState, readShelterState, selectShelter, projectShelterState } from "./shelter-state";

/** 仅初始化安装库存，保留原 JSON 复制和 owned 返回引用，不提前执行 strict reader。 */
function installShelterState(role: RoleComponent, state: ShelterState) {
  return commitPreparedNativeAbility(role, "shelter", SHELTER_STATE_SLOT.prepare(state));
}

/** 保留 assign 查找、状态读取和逐字段写入；next 已由原 caller 完成选择。 */
function recordShelterSelection(ability: NightAbilityReadView<"shelter">, next: ShelterState): void {
  // 原顺序：查 Object.assign → 读原 ability.state → 按 next 字段顺序赋值，绝不替换槽引用。
  Object.assign(ability.state, next);
}

/** 原政策 codec 保持 JSON callee 在 state/policy 读取之前，失效仍由 scope 判定。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"shelter">): string {
  return JSON.stringify([ability.state.policy]);
}

export const SHELTER_STATE_SLOT = Object.freeze({
  create: createShelterState,
  prepare: copyAbilityData<ShelterState>,
  schema: readShelterState,
  select: selectShelter,
  project: projectShelterState,
  install: installShelterState,
  allowedWrites: Object.freeze({ recordShelterSelection }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 负责幸运儿或黑市受赠者的晚执行能力阶段。
 * 输入为捕获的受赠实例和已校验行动；输出保留效果、库存、次数与受赠提交的原顺序。
 * 原毒来源复用既有 abilityId／目标参数读取，不新增 getter、资格重检或资源回滚。
 * 查验先调用状态 owner 再提交子狐效果；本模块不替换状态槽，也不记录运行时原体句柄。
 */
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { Camp, Phase, PotionType, StatusMark, type ToolName } from "../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  originalPoisonIntent,
  type NightLifeScope,
} from "../../../core/domain/night_effects";
import type { World } from "../../../core/domain/world";
import type { NightStageHandler } from "../stages/night/contracts";
import { allNightAbilities, abilityStatus, type NightAbilityReadView } from "./abilities";
import { recordNightAbilityUse } from "./ability_changes";
import { captureNightAbilityScope } from "./ability_scope";
import { luckyTargetAllowed, recordOwnNightAction } from "./night_action_history";
import { resolveInspection } from "./inspection";
import { SEER_STATE_SLOT } from "./seer/ports";
import { GUARD_STATE_SLOT } from "./guard/ports";
import { WITCH_STATE_SLOT } from "./witch/ports";

type RecipientPolicy = "lucky" | "black_market";
const committed = new WeakMap<World, Map<RecipientPolicy, Set<number>>>();
export function hasRecipientNightCommit(
  world: World,
  day: number,
  policy: RecipientPolicy,
): boolean {
  return committed.get(world)?.get(policy)?.has(day) ?? false;
}
export function recordRecipientNightCommit(
  world: World,
  day: number,
  policy: RecipientPolicy,
): void {
  const policies = committed.get(world) ?? new Map<RecipientPolicy, Set<number>>(),
    days = policies.get(policy) ?? new Set<number>();
  days.add(day);
  policies.set(policy, days);
  committed.set(world, policies);
}

import { captureInspectionIdentity, commitFoxInspection } from "./cursed_fox/inspection_effect";

type LuckyAbility = NightAbilityReadView<"seer_check" | "potion" | "guard">;
function isRecipient(
  ability: NightAbilityReadView,
  policy: RecipientPolicy,
): ability is LuckyAbility {
  return (
    ability.activation === policy &&
    (policy === "black_market"
      ? ["seer_check", "potion"]
      : ["seer_check", "potion", "guard"]
    ).includes(ability.kind)
  );
}

export function recipientAbilityStage(
  policy: RecipientPolicy,
  priority: number,
): NightStageHandler {
  return {
    id: policy === "lucky" ? "lucky_ability" : "black_market_recipient",
    priority,
    async execute(ctx) {
      const day = ctx.currentDay();
      for (const actorId of ctx.world.getAliveEntityIds()) {
        const role = ctx.world.getComponent(actorId, COMPONENT.Role);
        for (const ability of allNightAbilities(role).filter((ability) =>
          isRecipient(ability, policy),
        )) {
          if (abilityStatus(ability, day) !== "active") continue;
          const scope = captureNightAbilityScope(ctx.world, actorId, ability, day, ctx.isCurrent);
          if (!scope) continue;
          const current = () =>
            scope.isEligible() &&
            ability.activation === policy &&
            (ability.kind !== "potion" || ability.state.poison > 0);
          if (!current()) continue;
          const tool: ToolName =
            ability.kind === "seer_check"
              ? "check_identity"
              : ability.kind === "guard"
                ? "guard"
                : "use_potion";
          const kind =
            ability.kind === "seer_check" ? "check" : ability.kind === "guard" ? "guard" : "poison";
          const skip = () => {
            recordNightAbilityUse(ability, day, false);
            recordRecipientNightCommit(ctx.world, day, policy);
            ctx.events.push({
              timestamp: Date.now(),
              type: "lucky_ability_skipped",
              payload: { actorId, abilityId: ability.id, day, kind: ability.kind },
            });
          };
          let completed = false;
          for (let attempt = 0; attempt < 3; attempt++) {
            if (!current()) break;
            // 在原校验参数和目标查找位置捕获，避免来源信息再次读取行动 getter。
            let effectAbilityId: string;
            let effectRequestedTargetId: number | null = null;
            const targets = new Map(
              ctx.world
                .getAliveEntityIds()
                .filter((id) => luckyTargetAllowed(ctx.world, actorId, ability, day, kind, id))
                .map((id) => [id, captureNightLife(ctx.world, id)!] as const),
            );
            const identities = new Map(
              [...targets].map(([id, life]) => [id, captureInspectionIdentity(ctx.world, life)]),
            );
            if (ability.kind === "seer_check" && !targets.size) {
              skip();
              completed = true;
              break;
            }
            const action = await ctx.actionProvider.getAction(
              ctx.makeRequest(actorId, [tool], {
                stage: policy === "lucky" ? "lucky" : "black_market_recipient",
                requiresAction: false,
                ...(policy === "black_market"
                  ? { action_failure_policy: "error" as const, allow_fallback: false }
                  : {}),
                ability_id: ability.id,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            );
            if (!current()) break;
            if (action === null) {
              skip();
              completed = true;
              break;
            }
            if (action.name !== tool) continue;
            const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
              phase: Phase.Night,
              day,
              abilityId: (effectAbilityId = ability.id),
            });
            if (!current() || !result.ok || !result.sanitizedCall) continue;
            const call = result.sanitizedCall;
            if (
              (call.name === "guard" && call.args.abstain) ||
              (call.name === "use_potion" && call.args.potion_type === PotionType.None)
            ) {
              skip();
              completed = true;
              break;
            }
            if (
              !["guard", "use_potion", "check_identity"].includes(call.name) ||
              !("target_id" in call.args)
            )
              continue;
            const target =
              call.args.target_id === null
                ? undefined
                : targets.get((effectRequestedTargetId = call.args.target_id));
            if (!target || !livingNightLife(ctx.world, target)) continue;
            if (!luckyTargetAllowed(ctx.world, actorId, ability, day, kind, target.id)) continue;
            if (call.name === "check_identity" && ability.kind === "seer_check") {
              if (!identities.get(target.id)?.isCurrent()) continue;
              const result = resolveInspection(ctx.world, target.id, "camp", ctx.roleCatalog);
              if (
                !result ||
                !current() ||
                !identities.get(target.id)?.isCurrent() ||
                !livingNightLife(ctx.world, target) ||
                !luckyTargetAllowed(ctx.world, actorId, ability, day, kind, target.id)
              )
                continue;
              const isWerewolf = result.camp === Camp.Wolf;
              SEER_STATE_SLOT.allowedWrites.recordRecipientSeerInspection(ability, target, isWerewolf, result);
              commitFoxInspection(ctx.world, ctx.state, target, day, () =>
                scope.isOwnerCurrent(true),
              );
              ctx.state.seerChecks.push({
                seerId: actorId,
                targetId: target.id,
                isWerewolf,
                result: { ...result },
              });
              ctx.events.push({
                timestamp: Date.now(),
                type: "seer_checked",
                payload: {
                  actorId,
                  abilityId: ability.id,
                  targetId: target.id,
                  isWerewolf,
                  result: { ...result },
                },
              });
            } else if (call.name === "guard" && ability.kind === "guard") {
              const marks = ctx.ensureMarks(target.id);
              marks.add(StatusMark.GuardMark);
              (ctx.state.guardClaims ??= []).push({ target, marks });
              GUARD_STATE_SLOT.allowedWrites.recordRecipientGuardTarget(ability, target);
              ctx.events.push({
                timestamp: Date.now(),
                type: "guard_applied",
                payload: { actorId, abilityId: ability.id, abstain: false, targetId: target.id },
              });
            } else if (
              call.name === "use_potion" &&
              call.args.potion_type === PotionType.Poison &&
              ability.kind === "potion" &&
              ability.state.poison > 0
            ) {
              let effectSource: NightLifeScope;
              (ctx.state.poisonClaims ??= []).push(
                originalPoisonIntent(
                  {
                    source: (effectSource = scope.life),
                    target,
                    ...(policy === "black_market"
                      ? {
                          isCurrent: () =>
                            ctx.isCurrent() &&
                            ctx.currentDay() === day &&
                            scope.isOwnerCurrent(true),
                        }
                      : {}),
                  },
                  {
                    family: policy === "lucky" ? "lucky" : "black-market",
                    day,
                    stage: policy === "lucky" ? "lucky" : "black_market_recipient",
                    actorLife: effectSource,
                    requestedTargetId: effectRequestedTargetId,
                    abilityId: effectAbilityId,
                  },
                ),
              );
              ctx.ensureMarks(target.id).add(StatusMark.PoisonMark);
              WITCH_STATE_SLOT.allowedWrites.consumeRecipientPoison(ability);
              ctx.events.push({
                timestamp: Date.now(),
                type: "witch_potion_used",
                payload: {
                  actorId,
                  abilityId: ability.id,
                  targetId: target.id,
                  potionType: PotionType.Poison,
                },
              });
            } else continue;
            recordNightAbilityUse(ability, day, true);
            recordOwnNightAction(ctx.world, actorId, day, kind, target.id, true, policy);
            recordRecipientNightCommit(ctx.world, day, policy);
            completed = true;
            break;
          }
          if (!completed && current()) {
            if (
              ability.kind === "seer_check" &&
              !ctx.world
                .getAliveEntityIds()
                .some((id) => luckyTargetAllowed(ctx.world, actorId, ability, day, "check", id))
            )
              skip();
            else
              throw new Error(
                policy === "black_market"
                  ? "black_market_recipient_valid_action_missing"
                  : "lucky_valid_action_missing",
              );
          }
        }
      }
    },
  };
}

/**
 * 负责石像鬼、通灵师与镜女的原角色查验阶段。
 * 输入为查询端口给出的活动实例与已验证目标；输出保留角色报告、次数和可选结束行为。
 * 共享资格查询先行，历史委托具体状态 owner，use metadata 委托实例 owner。
 * 各族失败、目标、学习、作用资格和事实发布顺序保持，不合并其不同规则。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import type { RoleInspectionPolicy } from "@ai-werewolf-arena/game-contract";

import { ROLE_INSPECTION_STATE_SLOT } from "./state-slot";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Phase, Role } from "../../../../core/domain/model";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { type NightAbilityReadView } from "../abilities";
import { recordNightAbilityUse } from "../ability_changes";
import { getGargoyleState } from "../gargoyle/ports";
import { resolveInspection } from "../inspection";
import {
  beginRoleInspectionNight,
  recordRoleInspectionCompletion,
  recordRoleInspectionNightCommit,
} from "./night_scope";
import { inspectionRequired } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { roleInspectionTargets } from "./rules";
import { captureNightAbilityScope } from "../ability_scope";
import { captureAwakenedMirrorScope } from "../awakened_hidden_wolf/night_scope";

function finishOptionalInspection(
  ctx: NightStageContext,
  actorId: number,
  ability: NightAbilityReadView<"role_check">,
  day: number,
  reason: "passed" | "no_targets",
): void {
  recordNightAbilityUse(ability, day, false);
  ctx.events.push({
    timestamp: Date.now(),
    type: "role_inspection_skipped",
    payload: {
      actorId,
      ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
      day,
      reason,
    },
  });
  recordRoleInspectionNightCommit(ctx.world, day, ctx.isCurrent);
}
async function executeInspections(
  ctx: NightStageContext,
  policy: RoleInspectionPolicy,
): Promise<void> {
  const day = ctx.currentDay();
  if (policy === "gargoyle") beginRoleInspectionNight(ctx.world, day);
  for (const { actorId, ability } of ctx.nightActors.actors("role_check", day)) {
    if (!ctx.isCurrent()) return;
    if (roleInspectionPolicy(ability.state) !== policy) continue;
    const scope = captureNightAbilityScope(
      ctx.world,
      actorId,
      ability,
      day,
      () => ctx.isCurrent() && ctx.currentDay() === day,
    );
    if (!scope) continue;
    const role = scope.role,
      gargoyleState = getGargoyleState(role),
      state = ability.state,
      abilityId = ability.id;
    const source = ability.source,
      sourceKind = source.kind;
    const sourceOwner = source.kind === "native" ? source.role : source.actorId;
    const sourceAbilityId =
      source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined;
    const awakenedCurrent =
      source.kind === "native" && source.role === Role.AwakenedHiddenWolf
        ? captureAwakenedMirrorScope(
            ctx.world,
            actorId,
            ability,
            day,
            () => ctx.isCurrent() && ctx.currentDay() === day,
          )
        : () => true;
    const current = () =>
      awakenedCurrent?.() === true &&
      scope.isEligible() &&
      getGargoyleState(role) === gargoyleState &&
      roleInspectionPolicy(state) === policy &&
      ability.source === source &&
      source.kind === sourceKind &&
      (source.kind === "native" ? source.role : source.actorId) === sourceOwner &&
      (source.kind === "copy" || source.kind === "transfer" ? source.abilityId : undefined) ===
        sourceAbilityId;
    const exhausted = () =>
      policy === "gargoyle"
        ? recordRoleInspectionCompletion(ctx.world, actorId, day, ability, ctx.isCurrent)
        : finishOptionalInspection(ctx, actorId, ability, day, "no_targets");
    if (!current()) continue;
    if (!roleInspectionTargets(ctx.world, actorId, state).length) {
      exhausted();
      continue;
    }
    let completed = false;
    for (let attempt = 0; attempt < 3; attempt++) {
      if (!current()) break;
      const targets = new Map(
        roleInspectionTargets(ctx.world, actorId, state).map((id) => {
          const target = ctx.world.getComponent(id, COMPONENT.Alive)!;
          return [id, { target, version: aliveLifeVersion(target) }] as const;
        }),
      );
      if (!targets.size) {
        exhausted();
        completed = true;
        break;
      }
      const request = ctx.makeRequest(actorId, ["inspect_role"], {
        stage:
          policy === "gargoyle"
            ? "role_inspection"
            : policy === "mirror"
              ? "mirror_girl"
              : "psychic",
        requiresAction: inspectionRequired(state),
        ability_id: abilityId,
        ...(sourceKind === "native" && sourceOwner === Role.AwakenedHiddenWolf
          ? { action_failure_policy: "error" as const, allow_fallback: false }
          : {}),
        ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
      });
      if (!current()) break;
      const action = await ctx.actionProvider.getAction(request);
      if (!current()) break;
      if (action === null && !inspectionRequired(state)) {
        finishOptionalInspection(ctx, actorId, ability, day, "passed");
        if (policy === "gargoyle")
          recordRoleInspectionCompletion(ctx.world, actorId, day, ability, ctx.isCurrent);
        completed = true;
        break;
      }
      if (action?.name !== "inspect_role") continue;
      const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
        phase: Phase.Night,
        day,
        abilityId,
      });
      if (!current() || !validated.ok || validated.sanitizedCall?.name !== "inspect_role") continue;
      const targetId = validated.sanitizedCall.args.target_id,
        target = targets.get(targetId);
      const targetCurrent = () =>
        !!target &&
        ctx.world.getComponent(targetId, COMPONENT.Alive) === target.target &&
        target.target.alive &&
        target.version !== undefined &&
        aliveLifeVersion(target.target) === target.version;
      if (!targetCurrent() || !roleInspectionTargets(ctx.world, actorId, state).includes(targetId))
        continue;
      const mapping = ctx.nativeNightTargets.mappedTarget(
        () => day,
        () => targetId,
      );
      const result = resolveInspection(
        ctx.world,
        mapping?.effectiveId ?? targetId,
        "role",
        ctx.roleCatalog,
      );
      if (
        !current() ||
        !targetCurrent() ||
        !result ||
        (mapping !== null && !mapping.isCurrent()) ||
        !roleInspectionTargets(ctx.world, actorId, state).includes(targetId)
      )
        continue;
      ROLE_INSPECTION_STATE_SLOT.allowedWrites.appendState(state, targetId, day, result);
      recordNightAbilityUse(ability, day, true);
      ctx.events.push({
        timestamp: Date.now(),
        type: "role_inspected",
        payload: {
          actorId,
          ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
          targetId,
          day,
          result: { ...result },
        },
      });
      if (policy === "gargoyle")
        recordRoleInspectionCompletion(ctx.world, actorId, day, ability, ctx.isCurrent);
      else recordRoleInspectionNightCommit(ctx.world, day, ctx.isCurrent);
      completed = true;
      break;
    }
    if (!completed && current()) {
      if (roleInspectionTargets(ctx.world, actorId, state).length)
        throw new Error(
          policy === "gargoyle"
            ? "role_inspection_required_action_missing"
            : "role_inspection_valid_action_missing",
        );
      exhausted();
    }
  }
}
export const ROLE_INSPECTION_STAGE: NightStageHandler = {
  id: "role_inspection",
  priority: 180,
  execute: (ctx) => executeInspections(ctx, "gargoyle"),
};
export const PSYCHIC_INSPECTION_STAGE: NightStageHandler = {
  id: "psychic_inspection",
  priority: 600,
  execute: (ctx) => executeInspections(ctx, "psychic"),
};

export const MIRROR_INSPECTION_STAGE: NightStageHandler = {
  id: "mirror_inspection",
  priority: 600,
  execute: (ctx) => executeInspections(ctx, "mirror"),
};

/**
 * 负责角色查验能力族的原生状态创建、既有政策校验、同实例访问及两条历史写入前缀。
 * 输入为原角色／能力引用与已验证报告；输出保留原 JSON 复制、policy 默认解释、原状态
 * 引用与局部 payload 失效规则。查验目标、次数、生命、来源、阶段与租约仍归原 owner。
 * 本族覆盖五种原生政策和觉醒隐狼晚学习，赠予／复制／转移仍使用共享实例库存；
 * 不复制第二仓库、不严格化旧 payload、退款或推导新权限。
 */
import type {
  RoleInspectionState,
  RoleInspectionReadState,
} from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "@ai-werewolf-arena/game-contract";
import type { InspectionResult } from "@ai-werewolf-arena/game-contract";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { commitPreparedNativeAbility } from "../prepared-native-install";

export function setRoleInspectionState(
  role: RoleComponent,
  state: RoleInspectionState,
): RoleInspectionReadState {
  return commitPreparedNativeAbility(role, "role_check", ROLE_INSPECTION_STATE_SLOT.create(state));
}

export function getRoleInspectionState(
  role: RoleComponent,
  abilityId?: string,
): RoleInspectionReadState | undefined {
  return findNightAbility(role, "role_check", abilityId)?.state;
}

/** 调用方保留全部预检，以及随后次数、效果和事件发布；此处仅写原 payload 历史前缀。 */
export function recordRoleInspection(
  state: RoleInspectionReadState,
  targetId: EntityId,
  day: number,
  result: Extract<InspectionResult, { kind: "role" }>,
): void {
  (state as RoleInspectionState).lastTarget = targetId;
  (state as RoleInspectionState).lastDay = day;
  (state as RoleInspectionState).history.push({ day, targetId, result: { ...result } });
}

/** 纯白／狼巫仍逐次读取 ability.state 三次，并只追加一次结果历史。 */
export function recordAbilityRoleInspection(
  ability: import("../abilities").NightAbilityReadView<"role_check">,
  targetId: EntityId,
  day: number,
  result: Extract<InspectionResult, { kind: "role" }>,
): void {
  (ability.state as RoleInspectionState).lastTarget = targetId;
  (ability.state as RoleInspectionState).lastDay = day;
  (ability.state as RoleInspectionState).history.push({ day, targetId, result: { ...result } });
}

/** 原生安装先按原 JSON 规则复制，再校验原 policy；不增加 history／目标形状拒绝政策。 */
function createRoleInspectionState(state: RoleInspectionState): RoleInspectionState {
  const ownedState = copyAbilityData(state);
  roleInspectionPolicy(ownedState);
  return ownedState;
}

/** 保持 JSON.stringify 方法查找先于两次 ability.state 读取，不提前捕获状态或政策字段。 */
function encodeRoleInspectionPolicy(ability: NightAbilityReadView<"role_check">): string {
  return JSON.stringify([ability.state.policy, ability.state.inspectionPolicy]);
}

/** 原完成回执仅捕获 payload 关联；生命、id、来源、激活、当前阶段和禁用仍归原夜间 owner。 */
interface CapturedInspectionPayload {
  readonly ability: NightAbilityReadView<"role_check">;
  readonly inspection: RoleInspectionReadState;
  readonly inspectionPolicy: RoleInspectionReadState["inspectionPolicy"];
}
function capturedInspectionPayloadChanged(scope: CapturedInspectionPayload): boolean {
  return (
    scope.ability.state !== scope.inspection ||
    scope.inspection.inspectionPolicy !== scope.inspectionPolicy ||
    roleInspectionPolicy(scope.inspection) !== "gargoyle"
  );
}

/**
 * 本族唯一状态槽贡献。create 使用原复制与政策校验；schema 只引用原既有政策验证器，
 * 不冒称已验证整个 history 或添加严格 schema。原 native／赠予／转移能力仍存在原 abilities。
 * 两条 append 入口分别保留捕获状态与三次实例 state 读取的旧轨迹，不合并次数提交。
 * checkpoint 仅编码原运行政策身份；归档仍由既有 checkpoint 完整克隆 privateState，
 * 本声明不创建第二 JSON 仓库、解码器或新 lease，不把 payload 当前性当作完整行动授权。
 */
export const ROLE_INSPECTION_STATE_SLOT = Object.freeze({
  create: createRoleInspectionState,
  schema: roleInspectionPolicy,
  install: setRoleInspectionState,
  get: getRoleInspectionState,
  allowedWrites: Object.freeze({
    appendState: recordRoleInspection,
    appendAbility: recordAbilityRoleInspection,
  }),
  checkpoint: Object.freeze({ policyIdentity: encodeRoleInspectionPolicy }),
  invalidations: Object.freeze({ payloadChanged: capturedInspectionPayloadChanged }),
});

/**
 * 负责普通预言家对捕获能力及目标权威的查验请求。
 * 输入为原夜上下文和校验行动；输出保留查验结果、状态、use 和事件效果。
 * 资格枚举走只读查询，具体 Seer 状态与公共 use 命令在原 commit 位置执行；映射与子狐顺序不变。
 * Demon 封存原生控制器保持独立，不额外验证租约、退款或将原体信息写入玩家知识。
 */
import { SEER_STATE_SLOT } from "./ports";
/** 文件说明：预言家夜间查验阶段处理。 */
import { seerTargetAllowed } from "./ports";
import { COMPONENT } from "../../../../core/domain/components/names";
import { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { NightStageHandler } from "../../stages/night/contracts";
import { getSeerState } from "./ports";
import { resolveInspection } from "../inspection";
import { activeNightAbility } from "../abilities";
import { recordNightAbilityUse } from "../ability_changes";
import { captureNightAbilityScope } from "../ability_scope";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import { recordOwnNightAction, luckyTargetAllowed } from "../night_action_history";

import { captureInspectionIdentity, commitFoxInspection } from "../cursed_fox/inspection_effect";

const seerCheckStage: NightStageHandler = {
  id: "seer_check",
  priority: 600,
  async execute(ctx): Promise<void> {
    if (ctx.nativeNightFailure.usesDemonController()) {
      const { executeDemonNativeNight } = await ctx.nativeNightEffects.loadSealedNightController();
      await executeDemonNativeNight(ctx, "seer_check");
      return;
    }
    for (const { actorId: seerId, ability } of ctx.nightActors.actors(
      "seer_check",
      ctx.currentDay(),
    )) {
      if (ability.activation === "lucky" || ability.activation === "black_market") continue;
      ctx.nativeNightFailure.assertSeerSource(ability);
      ctx.nativeNightFailure.assertNativeActor(seerId, Role.Seer);
      const day = ctx.currentDay(),
        scope = captureNightAbilityScope(
          ctx.world,
          seerId,
          ability,
          day,
          () => ctx.isCurrent() && ctx.currentDay() === day,
        );
      if (!scope?.isEligible()) continue;
      const targets = new Map(
        ctx.world.getAliveEntityIds().map((id) => [id, captureNightLife(ctx.world, id)]),
      );
      const identities = new Map(
        [...targets].flatMap(([id, life]) =>
          life ? [[id, captureInspectionIdentity(ctx.world, life)] as const] : [],
        ),
      );
      if (
        !ctx.world.getAliveEntityIds().includes(seerId) ||
        activeNightAbility(
          ctx.world.getComponent(seerId, COMPONENT.Role),
          "seer_check",
          ctx.currentDay(),
          ability.id,
        ) !== ability
      )
        continue;
      const legalTargets = ctx.world
        .getAliveEntityIds()
        .filter(
          (id) =>
            seerTargetAllowed(ability.state, seerId, id) &&
            luckyTargetAllowed(ctx.world, seerId, ability, day, "check", id),
        );
      if (!legalTargets.length) continue;
      const req = ctx.makeRequest(seerId, ["check_identity"], {
        stage: "seer",
        ability_id: ability.id,
        requiresAction: ability.state.actionPolicy !== "awa_optional_v1",
      });
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      const action = await ctx.actionProvider.getAction(req);
      if (!ctx.isCurrent()) return;
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      if (action?.name !== "check_identity") {
        ctx.nativeNightFailure.actionMissing("seer");
        continue;
      }

      const result = ctx.toolGateway.validateAndSanitize(ctx.world, seerId, action, {
        phase: Phase.Night,
        day: ctx.currentDay(),
        abilityId: ability.id,
      });
      if (!ctx.isCurrent()) return;
      if (!scope.isEligible()) {
        ctx.nativeNightFailure.scopeStale("seer");
        continue;
      }
      if (!result.ok || !result.sanitizedCall) {
        ctx.nativeNightFailure.actionInvalid("seer");
        continue;
      }

      const targetId = result.sanitizedCall.args.target_id;
      const target = targets.get(targetId);
      if (!target || !livingNightLife(ctx.world, target) || !identities.get(targetId)?.isCurrent())
        continue;
      const mapping = ctx.nativeNightTargets.mappedTarget(
        () => day,
        () => targetId,
      );
      const receipt = ctx.nativeNightTargets.reflectedTarget(
        () => day,
        () => seerId,
        () => targetId,
        "check",
      );
      if (receipt && (ability.source.kind !== "native" || ability.source.role !== Role.Seer))
        throw new Error("time_consort_seer_source_invalid");
      const effectiveId = receipt?.effectiveId ?? mapping?.effectiveId ?? targetId;
      const effectiveIdentity = identities.get(effectiveId);
      if (mapping && (!mapping.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("magician_inspection_target_stale");
      const inspection = resolveInspection(ctx.world, effectiveId, "camp", ctx.roleCatalog);
      if (!ctx.isCurrent()) return;
      if (
        !scope.isEligible() ||
        !identities.get(targetId)?.isCurrent() ||
        !livingNightLife(ctx.world, target) ||
        !seerTargetAllowed(ability.state, seerId, targetId) ||
        !luckyTargetAllowed(ctx.world, seerId, ability, day, "check", targetId)
      )
        continue;
      if (mapping && (!mapping.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("magician_inspection_target_stale");
      if (!inspection) continue;
      const isWerewolf = inspection.camp === Camp.Wolf;
      const seerRole = ctx.world.getComponent(seerId, COMPONENT.Role);
      if (!activeNightAbility(seerRole, "seer_check", ctx.currentDay(), ability.id)) continue;
      const seerState = seerRole ? getSeerState(seerRole, ability.id) : undefined;
      if (receipt && (!receipt.isCurrent() || !effectiveIdentity?.isCurrent()))
        throw new Error("time_consort_inspection_target_stale");
      ctx.nativeNightEffects.commitReflectedTarget(receipt, day, seerId, "check");
      if (seerState) {
        SEER_STATE_SLOT.allowedWrites.recordSeerInspection(seerState, targetId, isWerewolf, inspection);
      }

      commitFoxInspection(ctx.world, ctx.state, target, day, () => scope.isOwnerCurrent(true));
      ctx.state.seerChecks.push({ seerId, targetId, isWerewolf, result: { ...inspection } });
      recordNightAbilityUse(ability, ctx.currentDay(), true);
      ctx.nativeNightEffects.recordModifierTarget(day, seerId, "check", () => targetId);
      ctx.nativeNightEffects.commitNativeReflection(
        "seer_check",
        ability,
        targetId,
        () => scope.life,
        () => scope.isOwnerCurrent() && !ability.disabled && !ability.deathExpired,
      );
      recordOwnNightAction(ctx.world, seerId, day, "check", targetId, false);
      ctx.events.push({
        timestamp: Date.now(),
        type: "seer_checked",
        payload: {
          actorId: seerId,
          ...(ability.source.kind === "native" ? {} : { abilityId: ability.id }),
          targetId,
          isWerewolf,
          result: { ...inspection },
        },
      });
    }
  },
};

/** 预言家夜间阶段列表。 */
export const SEER_NIGHT_STAGES: NightStageHandler[] = [seerCheckStage];

/**
 * 负责预言家原生／受赠查验状态的创建、同实例读取与实际报告写入。输入为原角色、
 * 捕获状态及已验证目标／阵营结果；输出保留 lastTarget、lastIsWerewolf、lastResult 与历史
 * 的原有序写入。普通查验消费捕获 state，受赠查验分别读取四次 ability.state 和两次 target.id，
 * 不能缓存或合并为一次写入。JSON 复制不新增 payload 形状校验，native 库存安装归 prepared owner；
 * 目标、次数、生命与请求资格仍归原 caller／lease，政策身份字节不替代档案编码或新授权。
 */
import type { SeerState, SeerReadState } from "@ai-werewolf-arena/game-contract";

import type { EntityId, InspectionResult } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../prepared-native-install";

/** 安装保留原输入复制与返回 owned 引用；只在初始化入口写原生库存。 */
export function setSeerState(roleComp: RoleComponent, state: SeerState): SeerReadState {
  return commitPreparedNativeAbility(roleComp, "seer_check", SEER_STATE_SLOT.create(state));
}

/** 原生优先选择不按活跃／耗尽过滤；读取不创建或补充资源。 */
export function getSeerState(
  roleComp: RoleComponent,
  abilityId?: string,
): SeerReadState | undefined {
  return findNightAbility(roleComp, "seer_check", abilityId)?.state;
}

/** caller 仍拥有目标／scope 检查及写前、写后的效果；部分失败不回滚前缀。 */
export function recordSeerInspection(
  state: SeerReadState,
  targetId: EntityId,
  isWerewolf: boolean,
  inspection: InspectionResult,
): void {
  (state as SeerState).lastTarget = targetId;
  (state as SeerState).lastIsWerewolf = isWerewolf;
  (state as SeerState).lastResult = { ...inspection };
  (state as SeerState).history.push({ targetId, isWerewolf, result: { ...inspection } });
}

/** 受赠查验保留每次写入前的 state 读取，以及原两次 target.id 读取，不缓存它们。 */
export function recordRecipientSeerInspection(
  ability: NightAbilityReadView<"seer_check">,
  target: { readonly id: EntityId },
  isWerewolf: boolean,
  result: InspectionResult,
): void {
  (ability.state as SeerState).lastTarget = target.id;
  (ability.state as SeerState).lastIsWerewolf = isWerewolf;
  (ability.state as SeerState).lastResult = { ...result };
  (ability.state as SeerState).history.push({
    targetId: target.id,
    isWerewolf,
    result: { ...result },
  });
}

/** 原 JSON callee 先于全部状态字段读取；只迁政策身份字节，不新增 payload snapshot 或失效租约。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"seer_check">): string {
  return JSON.stringify([ability.state.targetPolicy, ability.state.actionPolicy]);
}

/**
 * 本族完整契约引用原 JSON 复制函数和具体有序写入；create／schema 不改变旧接受集合。
 * install／get 与 caller 都消费同一实例库存，metadata 和 lease 保留唯一原所有者。
 * policyIdentity 是旧失效身份字节；checkpoint 归档并不调用新验证或改变原 privateState 形状。
 */
export const SEER_STATE_SLOT = Object.freeze({
  create: copyAbilityData<SeerState>,
  schema: copyAbilityData<SeerState>,
  install: setSeerState,
  get: getSeerState,
  allowedWrites: Object.freeze({
    recordSeerInspection,
    recordRecipientSeerInspection,
  }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 负责女巫每夜标记复位和原捕获瓶数/目标的用药选择。
 * 输入为当前 native/granted potion 与已验证行动；输出保留已付救/毒、跳过和历史。
 * 原毒 intent 从原 source/target/day 及原请求读取点捕获的 abilityId 生成，不增加时钟/World/RNG读取。
 * 付款、目标映射、第二次行动、角色专有失败和 poison-only 限制保持原位置。
 * 来源句柄只供运行时消费，不进入玩家信息或 schema2；瓶数／旗标归 Witch 状态 owner，公共次数归实例 owner。
 */
import { WITCH_STATE_SLOT } from "./ports";
/** 文件说明：女巫夜间用药阶段处理。 */
import {
  captureNightLife,
  livingNightLife,
  originalPoisonIntent,
} from "../../../../core/domain/night_effects";
import { COMPONENT } from "../../../../core/domain/components/names";
import { RoleComponent } from "../../../../core/domain/components/role";
import {
  Phase,
  PotionType,
  Role,
  StatusMark,
  WitchSelfHealRule,
} from "../../../../core/domain/model";
import { type NightAbilityReadView } from "../abilities";
import { nativePotionsCanCombine, witchKnifeVisible } from "./policies";
import { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import {
  getWitchState,
} from "./ports";
import { activeNightAbility, allNightAbilities } from "../abilities";
import { recordNightAbilityUse } from "../ability_changes";
import { recordOwnNightAction, luckyTargetAllowed } from "../night_action_history";
import { captureNightAbilityScope } from "../ability_scope";

const resetNightRoleStateStage: NightStageHandler = {
  id: "reset_night_role_state",
  priority: 100,
  async execute(ctx): Promise<void> {
    if (ctx.nativeNightFailure.usesDemonController()) return;
    for (const id of ctx.world.getAliveEntityIds()) {
      const role = ctx.world.getComponent(id, COMPONENT.Role);
      for (const ability of allNightAbilities(role)) {
        if (ability.kind !== "potion") continue;
        const witchState = ability.state;
        WITCH_STATE_SLOT.allowedWrites.resetWitchNightState(witchState, () => ctx.currentDay());
      }
    }
  },
};

const witchActionStage: NightStageHandler = {
  id: "witch_action",
  priority: 500,
  async execute(ctx): Promise<void> {
    if (ctx.nativeNightFailure.usesDemonController()) {
      if (!ctx.nativeNightFailure.requiresDemonPotionTurn()) return;
      const { executeDemonWitchTurn } = await ctx.nativeNightEffects.loadSealedPotionController();
      const result = await executeDemonWitchTurn({
        world: ctx.world,
        gateway: ctx.toolGateway,
        events: ctx.events,
        provider: ctx.actionProvider,
        day: ctx.currentDay(),
        wolfTarget: ctx.state.wolfTarget,
        construction: ctx,
      });
      if (result.poison) (ctx.state.poisonClaims ??= []).push(result.poison.claim);
      return;
    }
    for (const { actorId: witchId, ability } of ctx.nightActors.actors(
      "potion",
      ctx.currentDay(),
    )) {
      if (ability.activation === "lucky" || ability.activation === "black_market") continue;
      if (ctx.nativeNightFailure.skipsEmptyBorrowedPotion(ability)) continue;
      const day = ctx.currentDay();
      const ownership = captureNightAbilityScope(
        ctx.world,
        witchId,
        ability,
        day,
        () => ctx.isCurrent() && ctx.currentDay() === day,
      );
      if (!ownership?.isEligible()) continue;
      const close = () => {
        if (ownership.isOwnerCurrent() && !ability.disabled && !ability.deathExpired)
          WITCH_STATE_SLOT.allowedWrites.closeWitchPotionTurn(ability, day);
      };
      const both = nativePotionsCanCombine(ability);
      for (let turn = 0; turn < (both ? 2 : 1); turn++) {
        if (
          !activeNightAbility(
            ctx.world.getComponent(witchId, COMPONENT.Role),
            "potion",
            ctx.currentDay(),
            ability.id,
          )
        )
          break;
        const used = await executePotionTurn(ctx, witchId, ability);
        if (!ctx.isCurrent()) return;
        if (!used) {
          if (both) close();
          break;
        }
      }
      if (both) close();
    }
  },
};

/** 女巫夜间阶段列表。 */
export const WITCH_NIGHT_STAGES: NightStageHandler[] = [resetNightRoleStateStage, witchActionStage];

async function executePotionTurn(
  ctx: NightStageContext,
  witchId: number,
  ability: NightAbilityReadView<"potion">,
): Promise<boolean> {
  ctx.nativeNightFailure.assertNativeActor(witchId, Role.Witch);
  ctx.nativeNightFailure.assertPotionSource(ability);
  const day = ctx.currentDay();
  const scope = captureNightAbilityScope(
    ctx.world,
    witchId,
    ability,
    day,
    () => ctx.isCurrent() && ctx.currentDay() === day,
  );
  if (!scope?.isEligible()) return false;
  WITCH_STATE_SLOT.allowedWrites.refreshWitchSelfHeal(ability, day);
  const targets = new Map(
    ctx.world.getAliveEntityIds().map((id) => [id, captureNightLife(ctx.world, id)]),
  );
  const attribution = ability.source.kind === "native" ? {} : { abilityId: ability.id };
  let effectAbilityId: string;
  const req = ctx.makeRequest(witchId, ["use_potion"], {
    stage: "witch",
    ...ctx.nativeNightTargets.potionModifierHints(witchId),
    ability_id: (effectAbilityId = ability.id),
    ...(witchKnifeVisible(ability)
      ? {
          wolf_target: ctx.state.wolfTarget,
          ...ctx.nativeNightTargets.potionKnifeHints(),
        }
      : {}),
  });
  if (!scope.isEligible()) {
    ctx.nativeNightFailure.scopeStale("witch");
    return false;
  }
  const action = await ctx.actionProvider.getAction(req);
  if (!ctx.isCurrent()) return false;
  if (!scope.isEligible()) {
    ctx.nativeNightFailure.scopeStale("witch");
    return false;
  }
  if (action?.name !== "use_potion") {
    ctx.nativeNightFailure.actionMissing("witch");
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_skipped",
      payload: {
        actorId: witchId,
        ...attribution,
        targetId: null,
        potionType: PotionType.None,
        reason: "no_action",
      },
    });
    return false;
  }

  const result = ctx.toolGateway.validateAndSanitize(ctx.world, witchId, action, {
    phase: Phase.Night,
    day: ctx.currentDay(),
    abilityId: ability.id,
  });
  if (!ctx.isCurrent()) return false;
  if (!scope.isEligible()) {
    ctx.nativeNightFailure.scopeStale("witch");
    return false;
  }
  if (!result.ok || !result.sanitizedCall) {
    ctx.nativeNightFailure.actionInvalid("witch");
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_skipped",
      payload: {
        actorId: witchId,
        ...attribution,
        targetId: action.args.target_id ?? null,
        potionType: PotionType.None,
        reason: "invalid_action",
      },
    });
    return false;
  }

  const witch = ctx.world.getComponent(witchId, COMPONENT.Role);
  if (!activeNightAbility(witch, "potion", ctx.currentDay(), ability.id)) return false;
  const witchState = witch ? getWitchState(witch, ability.id) : undefined;
  if (!witchState) {
    return false;
  }
  const targetId = result.sanitizedCall.args.target_id;
  const potion = result.sanitizedCall.args.potion_type;
  const requestedTarget = targets.get(targetId);
  if (
    potion !== PotionType.None &&
    (!requestedTarget || !livingNightLife(ctx.world, requestedTarget))
  )
    return false;
  const mapping =
    potion !== PotionType.None
      ? ctx.nativeNightTargets.mappedTarget(
          () => day,
          () => targetId,
        )
      : null;
  if (mapping && !mapping.isCurrent()) throw new Error("magician_potion_target_stale");
  const receipt =
    potion === PotionType.Poison
      ? ctx.nativeNightTargets.reflectedTarget(
          () => day,
          () => witchId,
          () => targetId,
          "poison",
        )
      : null;
  if (receipt && (ability.source.kind !== "native" || ability.source.role !== Role.Witch))
    throw new Error("time_consort_witch_source_invalid");
  const effectiveId = receipt?.effectiveId ?? mapping?.effectiveId ?? targetId;
  const target = receipt?.scope ?? mapping?.scope ?? requestedTarget;

  if (potion === "heal") {
    if (
      witchState.heal <= 0 ||
      witchState.healUsedThisNight ||
      (witchState.poisonUsedThisNight && !nativePotionsCanCombine(ability))
    )
      return false;
    recordNightAbilityUse(ability, day, true);
    ctx.ensureMarks(effectiveId).add(StatusMark.HealMark);
    WITCH_STATE_SLOT.allowedWrites.consumeWitchHeal(witchState);
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_used",
      payload: { actorId: witchId, ...attribution, targetId, potionType: PotionType.Heal },
    });
  }

  if (potion === "poison") {
    if (
      witchState.poison <= 0 ||
      witchState.poisonUsedThisNight ||
      (witchState.healUsedThisNight && !nativePotionsCanCombine(ability))
    )
      return false;
    if (!luckyTargetAllowed(ctx.world, witchId, ability, day, "poison", targetId)) return false;
    const source = captureNightLife(ctx.world, witchId);
    if (!source || !target) return false;
    ctx.nativeNightEffects.commitReflectedTarget(receipt, day, witchId, "poison");
    recordNightAbilityUse(ability, day, true);
    (ctx.state.poisonClaims ??= []).push(
      originalPoisonIntent(
        { source, target },
        {
          family: "witch",
          day,
          stage: "witch",
          actorLife: source,
          requestedTargetId: targetId,
          abilityId: effectAbilityId,
        },
      ),
    );
    ctx.ensureMarks(effectiveId).add(StatusMark.PoisonMark);
    WITCH_STATE_SLOT.allowedWrites.consumeWitchPoison(witchState);
    ctx.nativeNightEffects.commitNativeReflection(
      "poison",
      ability,
      targetId,
      () => source,
      () => scope.isOwnerCurrent() && !ability.disabled && !ability.deathExpired,
    );
    recordOwnNightAction(ctx.world, witchId, day, "poison", targetId, false);
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_used",
      payload: { actorId: witchId, ...attribution, targetId, potionType: PotionType.Poison },
    });
  }

  if (potion === "none") {
    ctx.events.push({
      timestamp: Date.now(),
      type: "witch_potion_skipped",
      payload: { actorId: witchId, ...attribution, targetId, potionType: PotionType.None },
    });
  }
  if (potion === PotionType.None) recordNightAbilityUse(ability, day, false);
  ctx.nativeNightEffects.recordModifierTarget(day, witchId, "poison", () =>
    potion === PotionType.Poison ? targetId : null,
  );
  return potion !== PotionType.None;
}

/**
 * 负责普通药剂族原生安装、同实例读取及每条药瓶／夜旗标写入。输入为原角色、捕获
 * 状态或受赠实例；输出保留原库存引用和部分失败前缀。夜复位先写两个使用旗标，再按
 * 自救规则短路读取日期；refresh 保持左侧捕获和右侧重复 state 读取。原生药瓶减量与受赠
 * postfix 毒药减量及其第二次 state 读取各有独立程序，不能合并；Demon 原生封存控制器／
 * writer 仍独立。JSON 复制不新增 payload 拒绝，prepared owner 只装原库存；生命、claim、次数
 * 与租约仍归原 caller，政策身份字节不变成档案编码、退款或行动许可。
 */
import type { WitchState, WitchReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import { WitchSelfHealRule } from "@ai-werewolf-arena/game-contract";
import { copyAbilityData, findNightAbility, type NightAbilityReadView } from "../abilities";
import { commitPreparedNativeAbility } from "../prepared-native-install";

export function setWitchState(roleComp: RoleComponent, state: WitchState): WitchReadState {
  return commitPreparedNativeAbility(roleComp, "potion", WITCH_STATE_SLOT.create(state));
}

export function getWitchState(
  roleComp: RoleComponent,
  abilityId?: string,
): WitchReadState | undefined {
  return findNightAbility(roleComp, "potion", abilityId)?.state;
}

/** 两个复位写入及原规则判断之后才可能调用 currentDay；短路规则不多读日期。 */
export function resetWitchNightState(state: WitchReadState, currentDay: () => number): void {
  (state as WitchState).healUsedThisNight = false;
  (state as WitchState).poisonUsedThisNight = false;
  (state as WitchState).canSelfHeal =
    state.selfHealRule === WitchSelfHealRule.Always ||
    (state.selfHealRule === WitchSelfHealRule.FirstNightOnly && currentDay() === 1);
}

/** 保留左侧 state 捕获及右侧重复 state 读取；规则短路与写入时点不合并。 */
export function refreshWitchSelfHeal(
  ability: import("../abilities").NightAbilityReadView<"potion">,
  day: number,
): void {
  const state = ability.state;
  (state as WitchState).canSelfHeal =
    ability.state.selfHealRule === WitchSelfHealRule.Always ||
    (ability.state.selfHealRule === WitchSelfHealRule.FirstNightOnly && day === 1);
}

/** caller 在此写入前保持原 owner 当前性／来源检查；状态合法不替代该许可。 */
export function closeWitchPotionTurn(
  ability: import("../abilities").NightAbilityReadView<"potion">,
  day: number,
): void {
  (ability.state as WitchState).potionTurnClosedDay = day;
}

export function consumeWitchHeal(state: WitchReadState): void {
  (state as WitchState).heal -= 1;
  (state as WitchState).healUsedThisNight = true;
}

export function consumeWitchPoison(state: WitchReadState): void {
  (state as WitchState).poison -= 1;
  (state as WitchState).poisonUsedThisNight = true;
}

/** 受赠毒药保持 postfix 减量与第二次 state 读取，不能与原生药瓶付款合并。 */
export function consumeRecipientPoison(
  ability: import("../abilities").NightAbilityReadView<"potion">,
): void {
  (ability.state as WitchState).poison--;
  (ability.state as WitchState).poisonUsedThisNight = true;
}

/** 原 JSON callee 先于全部状态字段读取；只迁政策身份字节，不新增 payload snapshot 或失效租约。 */
function encodePolicyIdentity(ability: NightAbilityReadView<"potion">): string {
  return JSON.stringify([ability.state.selfHealRule,
    ability.state.knifeVisibility,
    ability.state.potionPolicy]);
}

/**
 * 本族完整契约引用原 JSON 复制函数和具体有序写入；create／schema 不改变旧接受集合。
 * install／get 与 caller 都消费同一实例库存，metadata 和 lease 保留唯一原所有者。
 * policyIdentity 是旧失效身份字节；checkpoint 归档并不调用新验证或改变原 privateState 形状。
 */
export const WITCH_STATE_SLOT = Object.freeze({
  create: copyAbilityData<WitchState>,
  schema: copyAbilityData<WitchState>,
  install: setWitchState,
  get: getWitchState,
  allowedWrites: Object.freeze({
    resetWitchNightState,
    refreshWitchSelfHeal,
    closeWitchPotionTurn,
    consumeWitchHeal,
    consumeWitchPoison,
    consumeRecipientPoison,
  }),
  checkpoint: Object.freeze({ policyIdentity: encodePolicyIdentity }),
  invalidations: Object.freeze({ policyIdentity: encodePolicyIdentity }),
});

/**
 * 场景测试验证夜能力共用契约。输入保留原 grant／copy／transfer／expiry 实例与原生配置；原字面回执、引用／getter／错误轨迹、事实和状态是预期。实际 NightPipeline 执行独立赠予实例、许可失效、到期与逐实例库存；模型由受控 provider 替代，生产输出不生成新 golden。
 */
import { completedNight } from "../../support/builders/night-stage-context";
import { PotionType } from "../../../src/core";
