    await pipeline.execute(sixPlayerMvpConfig, provider, 1);
    expect(asked.filter(([actor, stage]) => actor === 5 && stage === "seer")).toEqual([
      [5, "seer", "gift:one"],
      [5, "seer", "gift:two"],
