    expect(checks.map((event) => event.payload)).toEqual([
      {
        actorId: 5,
        abilityId: "gift:one",
        targetId: 1,
        isWerewolf: true,
        result: { kind: "camp", camp: "wolf" },
      },
      {
        actorId: 5,
