          ? { target_id: 1, abstain: false, hidden: true }
          : mode === "getter"
            ? {
                get target_id() {
                  reads++;
                  return 1;
                },
                abstain: false,
              }
            : mode === "proxy"
              ? new Proxy(
                  { target_id: 1, abstain: false },
                  {
                    ownKeys(t) {
                      reads++;
                      return Reflect.ownKeys(t);
                    },
                    get(t, key) {
                      reads++;
                      return Reflect.get(t, key);
                    },
                  },
                )
